Object.assign(window.__SYN,{"c:浮+缓": {"o": "浮缓脉总以浮为邪在表或气虚外浮，缓为风、湿、脾虚之象。其主病机可归纳为风邪伤卫、风湿郁表、太阴湿困、气虚脾弱、虚阳上浮、湿滞中焦及疟疾等类。风邪伤卫者，营卫不和，见有汗恶风；风湿郁表者，湿性黏滞，身重发热；太阴湿困者，脾土湿郁，可发黄或转阳明；气虚脾弱者，中气不足，运化失司；虚阳上浮者，下虚上实，冲逆痰壅；湿滞中焦者，湿困运化，身热不食；疟疾则邪客太阳，寒热间作。诸类之间，以风、湿、虚为共同要素，或外邪引动内虚，或虚中夹湿，或湿郁化热，总不离表里虚实之辨。", "c": [{"name": "主风邪伤卫", "desc": "浮缓脉主风邪外袭，卫气不固。浮为邪在表，缓为风性疏泄、营卫不和。原文如“脉浮缓，风中太阳经卫也”“浮缓为风邪伤卫，卫气不固”，症见有汗恶风、发热头痛，治以桂枝汤类调和营卫。"}, {"name": "主风湿郁表", "desc": "浮缓脉主风湿之邪郁于肌表。浮为邪在表，缓为湿性黏滞、营卫不和。原文如“风湿郁表，瘀热为黄”“脉浮缓，身不疼但重”，湿郁肌表则身重、发热汗出不解，治宜发散风湿。"}, {"name": "主太阴湿困", "desc": "浮缓脉主太阴脾土湿困。浮为邪在表，缓为脾土之湿。原文如“伤寒脉浮而缓，手足自温，是为系在太阴”，湿郁可发黄，小便自利则湿有出路；亦见湿从燥化转属阳明。"}, {"name": "主气虚脾弱", "desc": "浮缓脉主气虚、脾胃虚弱。浮为气虚外浮，缓为气弱不敛、脾运不及。原文如“脉皆浮缓，浮为阳热外浮，缓为气耗脾伤”“浮缓为气虚外浮，按之无根则中气大虚”，症见神倦、食少、自汗、下血等。"}, {"name": "主虚阳上浮", "desc": "浮缓脉主虚阳上浮、冲气上逆。浮为虚阳外浮，缓为虚或湿。原文如“浮主虚阳上浮，缓主湿或虚”，症见喘急涌痰、头痛、舌苔白黯，非表证，治宜滋阴降冲化痰。"}, {"name": "主湿滞中焦", "desc": "浮缓脉主湿邪内侵、困阻中焦。浮为湿邪在表，缓为湿性濡滞。原文如“右浮缓正是湿气内侵、困阻中焦之象”，症见身微热、无汗、不欲食，治宜燥湿运脾。"}, {"name": "主疟疾", "desc": "浮缓脉主疟疾，尤以太阳疟为典型。浮主太阳表邪，缓为风性弛张。原文如“左脉浮缓，太阳疟也”，疟邪客于太阳经，寒热间作，脉浮缓，治当和解截疟。"}], "n": {"主风邪伤卫": 29, "主风湿郁表": 13, "主太阴湿困": 6, "主气虚脾弱": 6, "主虚阳上浮": 1, "主湿滞中焦": 1, "主疟疾": 1}, "a": {"3397": "主气虚脾弱", "3911": "主风湿郁表", "4977": "主风湿郁表", "4980": "主风湿郁表", "8340": "主气虚脾弱", "8353": "主风邪伤卫", "15237": "主气虚脾弱", "15458": "主风邪伤卫", "15474": "主风邪伤卫", "15662": "主风邪伤卫", "15833": "主风邪伤卫", "15873": "主湿滞中焦", "16036": "主风邪伤卫", "16061": "主风湿郁表", "16628": "主虚阳上浮", "17376": "主太阴湿困", "18354": "主风邪伤卫", "18689": "主风邪伤卫", "18847": "主风湿郁表", "18920": "主太阴湿困", "18957": "主太阴湿困", "19886": "主气虚脾弱", "19994": "主风湿郁表", "19995": "主风邪伤卫", "20147": "主风邪伤卫", "20240": "主风湿郁表", "20834": "主风湿郁表", "20861": "主太阴湿困", "20886": "主太阴湿困", "21355": "主风邪伤卫", "21416": "主风湿郁表", "21621": "主气虚脾弱", "21638": "主风邪伤卫", "22042": "主风邪伤卫", "22146": "主风邪伤卫", "22949": "主风邪伤卫", "22961": "主太阴湿困", "23145": "主风邪伤卫", "23429": "主风邪伤卫", "24608": "主风邪伤卫", "24646": "主风邪伤卫", "24655": "主风邪伤卫", "24737": "主风邪伤卫", "24809": "主风邪伤卫", "24898": "主风湿郁表", "24933": "主风湿郁表", "24934": "主风湿郁表", "24955": "主风邪伤卫", "24984": "主疟疾", "25058": "主风邪伤卫", "25385": "主风湿郁表", "25820": "主风邪伤卫", "25822": "主风邪伤卫", "26135": "主气虚脾弱", "27183": "主风邪伤卫", "27343": "主风邪伤卫", "27766": "主风邪伤卫"}, "t": 57, "np": 0}, "c:微+缓": {"o": "微缓脉总起来主正气不足与邪退正复两类病机，以虚为本。微为阳气衰微、卫气疏泄，缓为脾胃虚弱、胃气尚存。其主虚，涵盖气血阴阳亏虚、脾胃虚寒、胃气衰败，甚则本虚标实、攻补两难；其主实，则见于卫疏荣盛之血崩，及外感邪退正复之欲愈。各类之间以“虚”为枢：微缓并见，虚多实少，或为纯虚，或为虚中夹实，或为邪退正复之佳兆。胃气之存亡尤为关键，微缓尚存一线柔和，故可调理脾胃以延生；若纯见微而恶寒，则阴阳俱虚，禁汗吐下。临证须结合部位与兼脉，辨其虚损之所在及邪正之进退。", "c": [{"name": "主虚（气血阴阳）", "desc": "微缓脉主气血阴阳亏虚。微为阳气衰微，缓为脾土虚弱，故见尺寸脉俱微缓而泄痢一载、气血两亏（10858、13666、14781）；或脉微缓而泄泻两月、仅余皮骨，为脾肾虚寒、下多亡阴（16629）；或中气下陷、困顿不能行（16632）。皆因正气不足，脉道不充，故显微缓。"}, {"name": "主脾胃虚寒", "desc": "微缓脉主脾胃虚寒、运化失职。如肾脉微缓为洞，食入还出，乃肾阳不足、火不暖土，胃中虚冷不能腐熟水谷（23222、23297）；脾脉微缓为风痿，四肢不用，因脾虚湿留、阳气不运（23596）；胃虚气逆之反胃，脉微缓、舌苔白，用大半夏汤补虚降逆（16656）。"}, {"name": "主胃气衰败", "desc": "微缓脉可主胃气衰败，但尚存一线生机。如六脉俱无胃气，惟胃脉略缓、脾脉微缓，胸前微痛无休，乃丹田阳气不到胸中，膈气无疑，调理脾胃犹可迁延（3686、4260）。微缓为真脏脉中稍见柔和之象，故虽胃气衰败，仍可借调理脾胃以延生。"}, {"name": "主邪退正复", "desc": "微缓脉主外感病邪退正复、欲愈之象。太阳病八九日，如疟状，发热恶寒，热多寒少，脉微缓者，为欲愈也（18830、18831、20821）。微缓示邪气渐衰、胃气渐和，正复邪退，故为向愈之兆；若脉微而恶寒，则阴阳俱虚，不可更汗吐下。"}, {"name": "主卫疏荣盛", "desc": "微缓脉主卫气疏泄、荣血盛而失统。寸口脉微而缓，微者卫气疏，疏则肤空；缓者胃气实，谷消水化，血乃成。荣盛则其肤必疏，三焦绝经，名曰血崩（18796、21118）。微缓并见，非纯虚纯实，乃卫疏胃实、荣盛失守之机，可致血崩。"}, {"name": "主本虚标实", "desc": "微缓脉可主本虚标实、攻补两难之证。如右关滑动主痰积中焦，左关弦搏主肝旺，尺寸脉俱微缓，泄痢一载，气血两亏，痰积湿热肝气交阻，须借元气以运之（10858、13666、14781）。微缓示元气已弱，而痰热郁结未去，故攻补皆难，唯择性味不猛者通化。"}], "n": {"主虚（气血阴阳）": 3, "主脾胃虚寒": 6, "主胃气衰败": 2, "主邪退正复": 3, "主卫疏荣盛": 2, "主本虚标实": 4}, "a": {"3686": "主胃气衰败", "4260": "主胃气衰败", "10858": "主本虚标实", "12076": "主虚（气血阴阳）", "13666": "主本虚标实", "14781": "主本虚标实", "16629": "主脾胃虚寒", "16632": "主脾胃虚寒", "16656": "主脾胃虚寒", "18424": "主本虚标实", "18796": "主卫疏荣盛", "18830": "主邪退正复", "18831": "主邪退正复", "19367": "主脾胃虚寒", "20821": "主邪退正复", "21118": "主卫疏荣盛", "22890": "主虚（气血阴阳）", "23222": "主脾胃虚寒", "23297": "主脾胃虚寒", "23596": "主虚（气血阴阳）"}, "t": 20, "np": 0}, "c:大+坚": {"o": "坚大脉总以「邪盛实积」为基本病机，坚主内结劲急，大主邪气亢盛。其主病约分两端：一为实邪壅盛，如风雨外袭、水气内停、积气结于脏腑、肾痹石水等，脉证相合，治当逐邪；二为正虚邪实之危候，久咳羸瘦而脉反坚大，形脉相反，胃气已败，故主死。此外，形充之人脉见坚大，为形气相任之顺象，不属病脉。诸类之中，邪盛实积为纲，水气、积气、肾痹皆实邪之具体表现；正虚邪实危候则由实邪与正虚并存而脉象失和；形气相符为顺则从平人角度反衬坚大脉之常。临证须结合形证，脉证相参，方能辨其吉凶。", "c": [{"name": "主邪盛实", "desc": "坚大脉主邪气壅盛、实积内停。原文如「脉坚大者，邪盛也」「六脉大且坚，大主邪盛，坚主实积」，风雨伤人「血气与邪并客于分腠之间，其脉坚大，故曰实」，皆以坚大为邪实壅滞之象。"}, {"name": "主积气内结", "desc": "坚大脉主积气结于脏腑。原文「赤脉之至也，喘而坚……有积气在中，名曰心痹」「黑脉上坚而大……肾痹积气」，坚主积气内结，大主病势亢盛，故五脏痹证见坚大脉者，皆积气为患。"}, {"name": "主肾痹石水", "desc": "坚大脉应肾，主肾之病。原文「脉大而坚……病在肾」，「微大为石水起，脐下以至少腹肿」，「上坚而大」为肾痹，肾脉「如引葛按之益坚为病」，皆以坚大示肾经邪实、水气或痹气内结。"}, {"name": "主正虚邪实危候", "desc": "久病虚损而脉反坚大，为正虚邪实、胃气已败之危候。如「咳嗽羸瘦，脉形坚大者，死」「咳而羸瘦，脉坚大者，死」，形羸而脉坚大，形脉相反，正虚不能胜邪，故主死。"}, {"name": "主形气相符为顺", "desc": "形盛之人脉见坚大，为形气相任、气血充盛之顺象。原文「形充而脉坚大者顺也」，形充脉亦坚大，气血与形体相称故顺；反之形充脉小弱则为气衰危候，坚大在此非病脉。"}, {"name": "色脉相参", "desc": "强调望色与切脉互参，以五脏应五色、五脉合五脏，察其应与不应、顺与不顺，从而由外知内、判断病邪逆顺。"}], "n": {"主邪盛实": 4, "主积气内结": 2, "主肾痹石水": 2, "主正虚邪实危候": 2, "主形气相符为顺": 2, "色脉相参": 1}, "a": {"12090": "主邪盛实", "17380": "主邪盛实", "18621": "色脉相参", "19212": "主正虚邪实危候", "19376": "主肾痹石水", "21138": "主正虚邪实危候", "21674": "主肾痹石水", "21801": "主邪盛实", "21824": "主形气相符为顺", "23026": "主邪盛实", "23081": "主积气内结", "23346": "主积气内结", "23706": "主形气相符为顺"}, "t": 13, "np": 0}, "pc:左+大+小": {"o": "左·大小脉总以左右脉象大小不等为特征，所主病机涉及虚损、邪热、肝胃不和、心肾不交及气血偏颇。左小右大多为营阴亏虚、邪热壅盛或肾水不足、心阳内亢；左大右小多属肝木偏亢、胃土不足，或阴不足而火扰、中气偏弱。各证之间相互关联：虚损可致邪陷，邪热可伤阴血，肝胃不和常兼痰瘀，心肾不交属内伤虚证，气血偏颇则贯穿诸证。总以阴阳气血失调、邪正虚实夹杂为要，临床须结合左右脉位及兼症辨析。", "c": [{"name": "主虚损", "desc": "左小右大或左大右小均可见虚损。左小为营阴亏虚、肾水不足，右大为虚阳外浮或心阳内亢；左大示阴不足而火扰，右小示中气偏弱。如内伤虚证、疟后元气阴不足、血室空虚等，脉象反映阴阳气血亏虚。"}, {"name": "主邪热", "desc": "右大主邪热壅盛，左小示营阴受抑或下焦受邪。如协热自利、伏暑夹湿夹积、暑风挟湿等，脉左小右大，为邪热内蕴、不得外达之象；左大右小亦可见肝热内炽。"}, {"name": "主肝胃不和", "desc": "左大右小，左大示肝木偏亢，右小示胃土不足。原文见胃痛屡发、呕吐酸苦、完谷而出、呃逆等，为肝木侮胃土、胃阳虚衰，兼凝痰聚瘀留于脘底。"}, {"name": "主心肾不交", "desc": "左小右大，左小为肾水亏虚不能上承，右大为心阳内亢反下趋肾，即坎离不交。症见淋浊尿血、宗筋绊痛、眩晕咳嗽、心中震跃，属内伤虚证，阴虚阳亢。"}], "n": {"主虚损": 4, "主邪热": 3, "主肝胃不和": 2, "主心肾不交": 2}, "a": {"1475": "主虚损", "1628": "主肝胃不和", "4535": "主肝胃不和", "11196": "主邪热", "11294": "主虚损", "13729": "主心肾不交", "14852": "主心肾不交", "15736": "主邪热", "15922": "主虚损", "21801": "主虚损", "24466": "主邪热"}, "t": 11, "np": 0}, "pe:左+涩": {"o": "左涩脉总以血少、血行不畅为基本病机，所主病机可归纳为血虚、血瘀、气滞、痰饮、虚寒、郁热、虚风七类。涩为脉道涩滞，血少则脉不充，血瘀则脉不利，故血虚与血瘀为其核心，二者常相因并存。气滞则血行不畅，痰饮阻滞气机，均可致涩；阳虚则血行无力，郁热则伤阴耗血，血虚则风动，皆可兼见涩脉。诸类之间相互兼夹，如气滞血瘀、血虚痰阻、阳虚血涩、郁热伤阴等。总起来说，左涩脉主病在血分，以虚为本，以滞为标，虚滞相兼，寒热错杂，须结合兼脉及症候辨其主次。", "c": [{"name": "主血虚", "desc": "左涩脉主血少精亏，脉道不充。原文多称“血液暗亏”“血少不濡”“阴血亏少”“精血少”，如右搏左涩为气燥在上、血液暗亏；左涩按之跃为肾阴空虚；左涩右濡弱为精血耗。涩为血行不畅，血少则脉涩，故主血虚。"}, {"name": "主血瘀", "desc": "左涩脉主血行瘀滞、脉络不通。原文见“血络郁滞”“气血凝结”“血因以阻”“血滞”，如左涩右弦为郁伤血络；左涩右弦为肝郁气血凝结、经不通行；左涩右濡为气弱血阻。涩主脉道不利，血瘀则涩，故主血瘀。"}, {"name": "主气滞", "desc": "左涩脉主气机郁滞、肝郁不舒。原文多称“肝郁不舒”“气郁”“气滞”，如左涩滞为肝郁不舒；左右俱涩为气郁日久；左涩右关沉弦为气郁湿阻。气滞则血行不畅，脉道涩滞，故涩主气滞。"}, {"name": "主痰饮", "desc": "左涩脉主痰饮内停、痰阻气机。原文见“饮邪为患”“积痰郁滞”“痰湿下注”，如左涩滞右弦滑为饮邪；左寸涩右寸滑为积痰郁滞于肺；左涩右弦滑为痰湿下注。痰饮阻滞气机，血行不畅，故脉涩。"}, {"name": "主虚寒", "desc": "左涩脉主阳气衰微、中焦虚寒。原文见“中宫阳气欲寂”“命火下衰”“阳虚阴亏”，如右涩左微为脾胃阳衰；左涩右濡弱为命火下衰、脾肾并虚；左涩右寸浮为阳虚阴亏。阳衰则血行无力，脉道涩滞，故主虚寒。"}, {"name": "主郁热", "desc": "左涩脉主郁热内蒸、火炎于上。原文见“郁热蒸腐”“相火上炎”“火炎于上”，如左涩右弦为郁热蒸腐；左寸涩关弦数为相火上炎；左涩右沉为气火升腾莫制。郁热伤阴，血行不畅，故脉涩。"}, {"name": "主虚风", "desc": "左涩脉主血虚风动、厥阳化风。原文见“新产暴虚，厥阳化风”“血虚风动”，如产后脉左涩为血少气滞、厥阳化风上旋。血虚则肝失所养，风阳上旋，脉道涩滞，故主虚风。"}], "n": {"主血虚": 9, "主血瘀": 5, "主气滞": 4, "主痰饮": 2, "主虚寒": 3, "主郁热": 2, "主虚风": 1}, "a": {"598": "主气滞", "900": "主血虚", "1390": "主血瘀", "3013": "主气滞", "4255": "主痰饮", "4431": "主血虚", "5020": "主虚寒", "6438": "主血虚", "6589": "主虚寒", "8619": "主气滞", "10354": "主血虚", "10415": "主虚寒", "11955": "主虚风", "12451": "主郁热", "12613": "主血虚", "12627": "主血瘀", "12879": "主痰饮", "12883": "主血虚", "15942": "主郁热", "15960": "主血虚", "17003": "主血瘀", "17036": "主血瘀", "17225": "主气滞", "17386": "主血瘀", "21801": "主血虚", "23973": "主血虚"}, "t": 26, "np": 0}, "pe:寸+小": {"o": "寸·小脉总以寸部脉体偏小为特征，所主病机可归纳为心阳不足、气血两虚、虚寒、阴虚火旺及痰浊内郁五类。其核心在于正气不足，或阳气虚弱鼓动无力，或阴血亏少脉道不充，故寸脉显小。虚寒类强调阳衰寒凝，阴虚类侧重阴亏火旺，二者一寒一热，然皆本于虚。痰浊内郁者，寸小为正气不足之基，兼他部流利或细软，示痰浊阻滞、本虚标实。诸类之间，虚为本，痰为标，虚实夹杂；心阳不足与气血两虚常相兼，虚寒与阴虚则依体质转化。临证当合参他部脉象及症候，辨其主次。", "c": [{"name": "主心阳不足", "desc": "寸脉略小，提示心阳不振，鼓动无力。原文谓“脉寸略小”而见顽痰郁闭心包、神呆语乱，乃心阳不足、痰浊阻滞神明之象；左寸小示阳弱，见汗出如雨、气急神呆，为阳弱不能固摄、痰浊上蒙。"}, {"name": "主气血两虚", "desc": "寸脉小为气血不足之征。原文左寸脉涩主血少，右脉耎小无力主气虚，症见经水愆期、体瘦食少，乃气虚血少、肝脾失和；“脉小血少病在心”，明言脉小与血少相关，心主血脉，寸小则心血不足。"}, {"name": "主虚寒（阳虚寒凝）", "desc": "寸脉小或阴脉小于寸口，主阳气虚衰、寒凝于内。原文等以阴脉小于寸口为虚寒之候，见胸中寒、短气、鼓胀、腰痛等；“肾脉逆小于寸口”为肾气不足、膀胱虚寒，故腰痛、胸中动。"}, {"name": "主阴虚火旺", "desc": "寸脉小而不劲，或虚弦软数，主阴亏阳不亢，虚火内扰。原文列“脉小不劲”“虚弦软数”“左寸关弦大以数”等，皆阴虚劳怯、咳嗽失血之脉，脉小为阴亏而阳不亢，虚火内扰则见数象。"}, {"name": "主痰浊内郁", "desc": "寸脉小兼他部流利，主痰浊内阻、气机郁滞。原文寸略小而右关流利，为痰浊内郁之象，顽痰郁闭心包，梗而不化；寸小兼右三部细软，痰浊壅肺，本虚标实，咳痰艰涩。"}], "n": {"主心阳不足": 1, "主气血两虚": 2, "主虚寒（阳虚寒凝）": 7, "主阴虚火旺": 1, "主痰浊内郁": 1}, "a": {"264": "主痰浊内郁", "15584": "主心阳不足", "15960": "主气血两虚", "21445": "主虚寒（阳虚寒凝）", "21490": "主虚寒（阳虚寒凝）", "21548": "主虚寒（阳虚寒凝）", "21626": "主虚寒（阳虚寒凝）", "21681": "主虚寒（阳虚寒凝）", "21695": "主虚寒（阳虚寒凝）", "21801": "主气血两虚", "21823": "主虚寒（阳虚寒凝）", "26892": "主阴虚火旺"}, "t": 12, "np": 0}, "pc:六+细+滑+微+伏+硬": {"o": "细滑微伏硬脉总起来主正虚邪实、虚实夹杂之候。其脉象由伏、滑、微、细、劲、硬复合而成：伏滑主邪毒内结肠胃，为实邪壅聚；微细主老人阴虚、津液枯竭，为正气亏虚；劲硬主邪毒锢结不解，气血阻滞。诸象并见，揭示正虚与邪实并存，虚者阴虚津枯，实者邪毒结聚，且邪毒因虚而锢结，因结而更伤正，形成恶性循环。临床见于疫病危候，满面通红、胸腹拒按、不饮不食，形如死人，治当扶正攻邪，泻下秽便后养阴退热解毒。各类病机相互关联，不可孤立看待。", "c": [{"name": "主邪毒内结", "desc": "脉见伏滑，伏为邪伏于里，滑为实邪壅聚，结合胸腹拒按、不饮不食，知邪毒结于肠胃，故主邪毒内结之实证。"}], "n": {"主邪毒内结": 1}, "a": {"12041": "主邪毒内结"}, "t": 1, "np": 0}, "c:数+细+虚+小": {"o": "细小数虚脉总属虚损之象，以阴血亏虚为本，虚热内扰为标。细主阴伤，虚主气弱，小主脉道不充，数主虚热。四段原文分别从阴虚内热、气阴两虚、肺虚肾亏、血虚劳伤立论，皆不离“虚”与“热”二字。其热为虚热，非实火；其虚或偏阴血，或偏气阴，或涉肺肾，或及心肝脾。诸类之间相互关联：阴血亏虚可致虚热内生，气阴两乏则无脏不虚，肺虚肾亏则相火上升，血虚劳伤则虚热与血滞并见。总以虚损为本，热象为标，病位涉及五脏，而尤以阴血亏耗为核心。", "c": [{"name": "主阴虚内热", "desc": "脉细主阴伤，数主内热，细小数并见为阴分不足、虚热内生之象。原文见素有血症、日午潮热，或肌灼溲赤，皆阴亏火浮所致，故主阴虚内热。"}, {"name": "主气阴两虚", "desc": "脉细小虚数，细虚为气阴亏耗、脉道不充，数则虚热内扰。原文见形肉消瘦、神思疲惫、怯寒疲惫，乃气阴两乏、无脏不虚之征，故主气阴两虚。"}, {"name": "主肺虚肾亏", "desc": "脉虚细小数，两尺濡耎。虚细为肺金虚，小数为相火升，濡耎为肾水不充。原文见喘咳呛血、逢节或劳心即发，乃肺虚肾亏、相火升而气逆，故主肺虚肾亏。"}, {"name": "主血虚劳伤", "desc": "脉虚小细数，兼见芤涩。细小为血虚脉道不充，芤涩为血痹不行；左寸细数心血不生，左关细数肝血不荣，右脉细数脾虚血少。数示虚热内扰，故主血虚劳伤。"}], "n": {"主阴虚内热": 1, "主气阴两虚": 1, "主肺虚肾亏": 1, "主血虚劳伤": 1}, "a": {"8194": "主阴虚内热", "9866": "主气阴两虚", "15751": "主肺虚肾亏", "24761": "主血虚劳伤"}, "t": 4, "np": 0}, "c:弦+滑+沉+小": {"o": "沉弦小滑脉总起来主痰饮内伏、痰火内扰，兼有正虚邪郁之机。沉主里，弦主饮，滑主痰，小示正气不足或邪郁，四者相合，提示痰饮或痰火内蕴于里，常因外感、劳倦、温邪或酒食引动而发病。各段原文均围绕痰饮、痰火展开：或外寒引动宿饮，或温邪酿痰化热，或疟后酒助火生痰，痰火内扰神明，或劳倦正虚邪乘。其病位涉及肺胃、少阳阳明，甚则连及厥阴、蒙蔽清窍。各类病机之间以“痰”为核心，或兼寒、兼热、兼正虚、兼邪郁，故临床见哮嗽气促、神识昏糊、狂乱便闭等症，治当降气涤痰、宣肺清窍、清火宁神，并兼顾正虚。", "c": [{"name": "主痰饮内伏", "desc": "脉沉弦小滑，沉主里、弦主饮、滑主痰，小示正气不足。原文见“外感风寒，引动宿饮”“引动素胜痰饮上泛”，痰饮内伏，遇外寒或温邪触发，上逆为哮嗽气促、痰多，故脉象主痰饮内伏。"}, {"name": "主痰火内扰", "desc": "脉小弦滑沉，弦主少阳，滑主痰，沉主里，小为邪郁。原文因疟多饮烧酒，酒助火生痰，痰火内扰神明，致如醉如狂、语言妄乱、昏昏默默，断为少阳阳明同病连及厥阴，脉象主痰火内扰。"}], "n": {"主痰饮内伏": 2, "主痰火内扰": 2}, "a": {"2386": "主痰饮内伏", "2390": "主痰饮内伏", "10781": "主痰火内扰", "14714": "主痰火内扰"}, "t": 4, "np": 0}, "c:弦+细+滑+虚": {"o": "虚弦细滑脉总起来主本虚标实之证，以阴液亏虚为本，痰热内壅为标。虚细反映少阴阴血不足，弦滑提示痰饮热邪内停，二者并见，形成阴虚挟痰、虚实夹杂之病机。各段原文中，或见喘嗽不能卧、进参汤反助痰，或见脘痛晕厥、胸闷气逆，皆因阴亏于下、痰热壅于上所致。三类病机中，主阴虚与主痰热分别对应脉象的虚细与弦滑成分，而主本虚标实则统括二者复合为病。临证须凭脉权衡虚实主次，虚多者重加熟地滋阴，痰热盛者以蒌薤旋覆开降，不可偏执一端。", "c": [{"name": "主阴虚", "desc": "虚弦细滑脉中虚细为阴血亏虚之象，如邵案花甲之年喘嗽，进参汤喘稍定而易汗，似虚脱；董案素患脘痛晕厥，脉虚细中兼弦滑，舌绛而渴，显系阴液不足。虚细脉直接反映少阴阴血亏虚，故主阴虚。"}, {"name": "主痰热", "desc": "弦滑脉主痰热内壅，右甚则痰热偏盛于肺。如邵案喘嗽坐不能卧，脉弦滑右甚，参汤切勿沾唇，以痰热壅肺、肝热上逆，进参汤反助热恋痰；董案胸闷气逆不能卧，脉兼弦滑，为痰饮内停。滑脉主痰，弦主饮，合为痰热之征。"}, {"name": "主本虚标实", "desc": "虚弦细滑脉并见，虚细为本虚（阴亏），弦滑为标实（痰热），形成虚实夹杂之候。如石媪脉虚弦细滑，孟英断为虚中夹痰，重加熟地而瘳；董案脉虚细中兼弦滑，断为阴虚挟痰。此脉总括正虚与邪实同存，治当兼顾。"}], "n": {"主阴虚": 1, "主痰热": 2, "主本虚标实": 1}, "a": {"13238": "主本虚标实", "14123": "主痰热", "14370": "主阴虚", "14417": "主痰热"}, "t": 4, "np": 0}, "c:数+大+浮+洪": {"o": "浮大洪数脉总起来主热，但须分虚实。实者多为痰热壅盛，如案中太阴经积痰，脉浮大洪数，痰热壅肺，肺失肃降；虚者或为虚阳外浮，如产后气血暴损，孤阳外越，内真寒外假热，脉浮大洪数；或为虚火上炎，如年高足三阴虚损，虚火不敛，脉洪数不减或洪大浮数按之无力。三类之间，实热与虚热迥异，临证当结合病史、症状及脉之有力无力辨别。浮大洪数虽主热，然虚证亦可见此脉，不可一概而论。", "c": [{"name": "主痰热壅盛", "desc": "脉浮大洪数，浮主上焦，洪数为痰热壅盛之象。如案中老人泄泻，脉见浮大洪数，断为太阴经有积痰，肺气壅遏，不能下降，大肠虚而作泻。此脉象揭示痰热壅肺、肺失肃降之病机，故主上焦积痰、痰热壅盛。"}, {"name": "主虚阳外浮", "desc": "脉浮大洪数，貌似实热，然产后暴损气血，孤阳外浮，内真寒而外假热，脉见浮大洪数乃虚阳浮越之象，非真热。用清凉则热增剧，投大补气血之剂则热减，反证此脉此证属气血虚极、虚阳外越。"}, {"name": "主虚火上炎", "desc": "脉洪数不减，或洪大浮数、按之无力，为足三阴虚损、虚火不敛。如案中年高足三阴虚损，脉洪数不减，后脉洪大浮数按之无力，断为虚火上炎，甚则血肉腐败而成肺痈，吐脓血。"}], "n": {"主痰热壅盛": 1, "主虚阳外浮": 1, "主虚火上炎": 1}, "a": {"3434": "主痰热壅盛", "4085": "主虚阳外浮", "4117": "主虚火上炎"}, "t": 3, "np": 0}, "c:数+大+洪+实": {"o": "洪大数实脉总属邪热亢盛、邪气壅实之象。洪主热盛，数主热急，实主邪实，大主病进，四者相合，突出热邪炽盛、正气未衰、邪正剧争之病机。其所主涵盖气分热实、热毒壅盛、暑热内伏及痰热蒙蔽心包等，皆以热实为共同基础。然兼脉与部位不同，病机有异：兼模糊者热蒸痰蒙，左右悬殊者邪伏阴阳逆乱。总之，此脉以实热为核心，或见于外感暑温，或见于疮疽热毒，总为邪气实而正气尚能抗邪之候，与虚寒脉弱形成鲜明对比。", "c": [{"name": "主邪实", "desc": "脉实大有力，主邪气盛实。疮疽辨证以脉大精神闷塞为脏腑之实，脉洪数者为实，皆因邪正相争，邪壅于内，气血充实，故脉应之实大。此与虚证脉弱皮寒相对，为辨虚实之要。"}, {"name": "主暑热内伏", "desc": "伏暑似疟案左脉洪大数实，右脉阳微，左右悬殊，为暑热之邪内伏，壅遏于左，不得透达，故脉洪大数实；邪伏难透，阴阳逆乱，故曰最难即愈。此脉主暑热内伏、邪壅不透之机。"}], "n": {"主邪实": 1, "主暑热内伏": 2}, "a": {"5174": "主暑热内伏", "5203": "主暑热内伏", "23917": "主邪实"}, "t": 3, "np": 0}, "c:细+滑+沉+紧": {"o": "沉细紧滑脉总属寒、虚、痰湿相合之象。沉主里，细主虚，紧主寒，滑主痰湿，四者合见，多示里虚寒盛、痰湿内停之病机。所主病机主要有三类：一为寒湿凝滞经脉，如痓症身体强硬；二为少阴中寒、阳气不振，如但欲寐、恶寒足冷；三为痰饮内停，如胸背胀痛、呕吐不能食。三类之间相互关联：寒邪与痰湿常相搏结，阳虚则寒湿痰饮易生，故临床可见寒湿凝滞、少阴中寒兼痰饮等复合病机。脉象紧滑有力者，又提示寒痰内盛而非纯虚寒，需结合症候辨其虚实主次。", "c": [{"name": "主寒湿凝滞", "desc": "沉主里、紧主寒，细为虚象，滑为湿痰。原文见六脉沉细紧滑、愈按愈有力，断为寒湿相搏、凝滞经脉，致身体强硬、牙关紧闭，属痓症。寒湿乘虚袭入，筋脉失柔，故脉紧滑有力非纯虚寒。"}], "n": {"主寒湿凝滞": 2}, "a": {"3293": "主寒湿凝滞", "16083": "主寒湿凝滞"}, "t": 2, "np": 0}, "c:弦+细+虚+弱": {"o": "虚弦细弱脉总属阴血亏虚、阳浮风动之候。虚、细、弱三象主阴血亏乏，弦象主阳不能潜、肝风内动。三者相合，反映素体阴亏、新产血去之后，八脉空虚，阳失所潜而游行于上。其见证错杂：咳嗽寒热、齿衄、善怒不眠、四肢牵掣、汗出等，皆阴亏阳浮、风阳上扰之象，非外感表邪，亦非瘀血实滞。三类病机相互关联：阴血亏虚为根本，奇经空虚为其中间环节，阳浮风动为其标象，总属本虚标实、下虚上盛之证。", "c": [{"name": "主阴血亏虚", "desc": "脉虚、细、弱三象并见，为阴血亏乏之征。原文谓「素属阴亏，新产血去之后，八脉皆空」，又见舌色无液、溺少口干、齿衄频流，皆阴血不足、奇经空虚之象，故虚细弱主阴血亏虚。"}], "n": {"主阴血亏虚": 2}, "a": {"13483": "主阴血亏虚", "13857": "主阴血亏虚"}, "t": 2, "np": 0}, "c:数+浮+洪+紧": {"o": "浮数洪紧脉总属阳脉，主阳热壅盛、六腑不和、热胜血壅之痈疽。其脉浮主病位在表，数主热，洪主热盛，紧主邪壅，合而示阳热之邪郁于肌表、壅于血分。原文以之与沉细伏紧之阴脉对举：浮数洪紧者，毒发于外而为痈，属六腑不和，症见肿焮作痛、身热烦渴、饮食如常，其势虽急，投凉剂多可保全；沉细伏紧者，毒蓄于内而为疽，属五脏不和。故本脉所主，总为阳热实证，病位在腑、在表，病机为热胜血壅、毒发于外，与阴寒内蓄之疽脉形成鲜明对比，示凭脉分阴阳虚实而定温清。", "c": [{"name": "主阳热痈疽", "desc": "脉浮数洪紧为阳脉，主阳热之邪郁于肌表。原文谓'痈疽只是热胜血'，'阳滞于阴则脉浮洪弦数'，又'毒发于外而为痈'，见肿焮作痛、身热烦渴，此六腑不和、热毒外发之象，故脉浮数洪紧主阳热壅盛之痈。"}], "n": {"主阳热痈疽": 2}, "a": {"18703": "主阳热痈疽", "23920": "主阳热痈疽"}, "t": 2, "np": 0}, "pc:右+弦+滑+沉+小": {"o": "右弦滑沉小脉总起来主痰饮内伏、正虚邪实之候。其脉象由沉、弦、小、滑四者复合而成：沉主里，示病位在里；弦主饮，滑主痰，示痰饮内盛；小示正虚，示正气不足。四者相合，反映痰饮内伏、温邪引动、正虚邪恋的复杂病机。右关带数，又专主脾胃痰热。各类病机之间相互关联：正虚（小）是基础，痰饮（弦滑）是病理产物，里实（沉）是病位所在，脾胃病（右关数）是病变中心。总属本虚标实、痰热内扰之证，治当宣肺涤痰、宁神清窍，兼顾正虚。", "c": [{"name": "主痰饮", "desc": "脉滑主痰，弦主饮。原文谓「酿痰化热，引动素胜痰饮上泛」，痰饮内伏，上泛蒙蔽清窍，故脉见弦滑。右关候脾胃，滑为痰涎内盛之象，弦为饮邪内动之征，合而主痰饮内停。"}], "n": {"主痰饮": 1}, "a": {"2390": "主痰饮"}, "t": 1, "np": 0}, "c:细+沉+弱+软": {"o": "沉细软弱脉总属正虚邪恋之象。沉细主里、主阴血不足，软弱主正气无力，故其核心病机为正虚，尤以阴津亏耗为主。然此案中虚中夹实：热邪炼津为痰，痰热内蕴，故见咳嗽痰黏、喉有痰声。脉象'较昨稍起'示正气渐复、阴津渐回，但未全复，故脉仍软弱。三类病机相互关联：正虚为本，阴津亏耗为虚之具体，痰热为虚中夹实之标。临证当扶正兼清痰热，保阴液为要。", "c": [{"name": "主正虚", "desc": "脉沉细软弱，沉为在里，细为阴血不足，软弱为正气无力。原文谓'沉细软弱主正气虚衰'，且'较昨稍起'说明虚象稍减，但正虚未复，故脉仍软弱。"}], "n": {"主正虚": 1}, "a": {"7269": "主正虚"}, "t": 1, "np": 0}, "pc:左+弦+细+急+促": {"o": "左弦细急促脉总起来主木火亢盛、阴亏火旺，兼夹湿浊内蕴及正虚邪陷。弦主木火，细促为阴亏火旺，反映肝木化火、阴液亏虚、气火内烁的核心病机；右脉濡滑提示湿浊内蕴，木火夹浊蒸腾，形成复杂病机。脉不耐重按，示正气已虚，邪热内陷，病势深重。诸类之间相互关联：阴亏为本，木火为标，湿浊为兼夹，正虚邪陷为转归，共同构成病久阴亏、木火夹浊、正虚邪陷的综合病机。", "c": [{"name": "主木火", "desc": "弦脉为肝木之象，主木火亢盛。原文谓“弦主木火”，左脉弦细急促，弦象明显，反映肝木化火，气火内烁，热从内陷，故木火为病机之一。"}], "n": {"主木火": 1}, "a": {"7352": "主木火"}, "t": 1, "np": 0}, "c:数+弦+细+缓": {"o": "细弦数缓脉总以细弦数为主，缓为兼象。细主阴伤，弦主肝旺气逆，数主火动，三者相合，总归阴虚火旺、肺肾阴伤、冲阳偏亢之病机。原文“肺肾阴伤不复”点明病本在阴亏，“冲阳稍平”示火势虽减而未清，故脉仍细弦数；而“稍缓”一象，乃数势略退、胃气渐和之征，主病势向缓而非病愈。四类之中，阴虚火旺为总纲，肺肾阴伤为其本，冲阳偏亢为其标，病势向缓则为转归之兆。诸类相互关联：阴伤则火旺，火旺则冲阳上逆，火势稍退则脉见稍缓，然阴伤未复，故细弦仍在，仍须金水双调以善其后。", "c": [{"name": "主阴虚火旺", "desc": "脉细弦数，细为阴伤，弦为肝旺，数为火动。原文谓“肺肾阴伤不复”，又“冲阳稍平”示火势虽减而未清，故细弦数主阴亏于下、火炎于上，虚火内扰之病机。"}], "n": {"主阴虚火旺": 1}, "a": {"7551": "主阴虚火旺"}, "t": 1, "np": 0}, "pc:六+数+弦+沉+微": {"o": "六·数弦沉微脉总起来主阳热闭郁、热动肝风之证。其脉象由沉微与弦数复合而成：沉微反映阳气郁伏，因惊闭气窒、热闭于内，阳不外达；弦数反映热盛动风，因小儿纯阳之体，受热则肝风内动。三者相互关联：惊则气乱，闭则气窒，导致阳热郁伏；郁伏之热不得外泄，进而热甚动风；风动又加重气机逆乱，形成恶性循环。故其病机核心为热闭于内、阳不外达，兼肝风内动，临床可见惊搐、气升痰鸣、肢冷面青、目直视等惊闭之候。", "c": [{"name": "主阳郁热闭", "desc": "脉沉微主阳气郁伏，因误捂受热、惊则气乱、闭则气窒，致阳热闭郁于内，不能外达，故脉沉微。原文'沉微主阳气郁伏'及'热闭于内、阳不外达'明示此机。"}], "n": {"主阳郁热闭": 1}, "a": {"11090": "主阳郁热闭"}, "t": 1, "np": 0}, "pc:左+弦+细+滑+大": {"o": "左·弦细滑大脉总起来主虚实夹杂之证，具体包括心肾阴血不足与痰涎壅盛两方面。左脉弦细反映心肾阴血亏虚，右脉滑大反映痰涎壅盛，两者并见提示正虚邪实。其病机核心为心肾两虚、痰涎沃胆，故临床可见神气模糊、夜不能寐、心忡、腰痛、舌苔黄垢等症。治疗需权衡虚实，先清后补。各类病机之间相互关联：虚为病之本，痰为病之标，标本同病，故脉象并见弦细与滑大。", "c": [{"name": "主虚", "desc": "左脉弦细为阴血不足之象。弦主肝郁，细主血虚，左脉候心肝肾，故弦细并见提示心肾阴血亏虚，不能濡养心神与腰府，故见神气模糊、夜不能寐、心忡、腰痛等症。"}], "n": {"主虚": 1}, "a": {"11358": "主虚"}, "t": 1, "np": 0}, "pc:右+弦+细+滑+虚": {"o": "右·弦细滑虚脉总起来主痰饮与正虚，以痰饮偏盛于肺为核心病机，兼见虚象。弦主饮、滑主痰，右甚则痰饮壅肺，故喘嗽坐不能卧；虚弦细滑则示病久正虚，痰饮未化。两类病机相互关联，痰饮为标实，正虚为本虚，临证需权衡虚实，治痰饮不忘顾虚，补虚勿助痰壅。", "c": [{"name": "主痰饮", "desc": "脉弦滑右甚，弦主饮、滑主痰，右甚则痰饮偏盛于肺。喘嗽坐不能卧，进参汤反助痰壅，故切勿沾唇。孟英以栝蒌薤白旋覆等开降痰饮，投匕即减。"}], "n": {"主痰饮": 1}, "a": {"14417": "主痰饮"}, "t": 1, "np": 0}, "pc:左+弦+细+沉+小": {"o": "左弦细沉小脉总起来主里、虚、邪郁，并综合为营虚邪陷之候。沉主里，细主虚，小主不足，弦主邪郁，四者相合，说明正气内虚而邪气内陷，病位在里，闭而未出。原文以“营弱卫强，阳邪内陷”为据，又值经断后得病，故营虚为本，邪陷为标，形成虚实夹杂之局。诸类之间，里与虚言其病位与正虚，邪郁言其邪闭，营虚邪陷则统括全脉，揭示正虚邪陷、闭阻不达的核心病机。", "c": [{"name": "主里", "desc": "脉沉主里，原文明言“沉主里”，且“左右脉俱沉细小弦”，结合头疼、齿痛等症，说明邪已由表入里，病位在里，非表证单纯可解。"}], "n": {"主里": 1}, "a": {"15951": "主里"}, "t": 1, "np": 0}, "c:数+微+弱+动": {"o": "数动微弱脉总属阴阳俱不足之虚证。其脉数动似热，微弱主虚，合而观之，乃虚家之象，根本在于气血阴阳亏虚。因虚致津液不足，故见大便难、腹中干、胃燥而烦；数动之热象仅为假象，与实热‘根本异源’。三类病机以‘主虚’为核心，‘主津亏’为虚之具体表现，‘主虚热假象’为脉象易混之辨，三者相互关联，皆围绕虚损本质，戒发汗以护津液。", "c": [{"name": "主虚", "desc": "脉数动而微弱，数动似热，微弱属虚，乃阴阳俱不足之象。原文明言‘微弱属虚’，‘阴阳俱不足’，故主虚证，尤以气血阴阳亏虚为根本。"}], "n": {"主虚": 1}, "a": {"19022": "主虚"}, "t": 1, "np": 0}, "pc:关+弦+细+虚+涩": {"o": "关·弦细虚涩脉总属虚实夹杂之候，以脾虚湿困、气血不足为本，气滞、肺气不足为标。关脉虚主脾胃虚弱，右脉弦细兼涩示血少气滞、脾虚湿困，寸脉短主肺气不足。诸脉并见，反映脾虚失运、湿邪内停，气血生化不足，进而气机阻滞、肺气不宣。临床见面黄、汗多、目赤、四肢沉重、减食、腹中时时痛、咳嗽，乃脾虚湿盛、气血不足、肺气不宣之候。各类病机之间相互关联：脾虚为本，湿困、气血不足由此而生；气血不足则气滞，脾虚则肺气亦弱，形成虚实夹杂之证。", "c": [{"name": "主脾虚湿困", "desc": "关脉虚主脾胃虚弱，弦细涩为脾虚湿困之象。原文见四肢沉重、减食、腹中时时痛，乃脾虚失运、湿邪内停所致。湿性重浊，故四肢沉重；脾虚不运，故减食、腹痛。"}], "n": {"主脾虚湿困": 1}, "a": {"19315": "主脾虚湿困"}, "t": 1, "np": 0}, "c:滑+浮+微+洪": {"o": "洪滑微浮脉总属热邪为患，以里热壅盛为核心，兼表邪未解。洪滑主里热炽盛，热邪内传阳明、壅阻膀胱，致水热互结，故见小便涩热、周身悉肿；热盛灼津为痰，痰热上泛，则痰涎上泛、微兼喘息；微浮示热邪尚连表分，表证未罢。四类病机相互关联：里热壅盛是根本，水热互结、痰热上泛为热邪所致之变，表热未解为兼夹之候。临证当以清里热为主，兼以解表、利水、化痰，方能切中病机。", "c": [{"name": "主里热壅盛", "desc": "洪滑脉象为里热炽盛之征，原文谓'洪滑主里热壅盛'。热邪内传阳明胃府，与糟粕相结，故见心中热渴、舌苔白厚；热壅膀胱，水道阻塞，则小便涩热、周身悉肿。此热盛于里，充斥脉道，故脉来洪滑有力。"}], "n": {"主里热壅盛": 1}, "a": {"19707": "主里热壅盛"}, "t": 1, "np": 0}, "c:微+涩+平+短": {"o": "微涩短平脉总以肺金为枢，其常为秋令收敛之平脉，其变为四时相乘之邪脉。微涩短三象合看，微主气敛、涩主肃降、短主应秋，故首主肺之平调；若失其根底而浮虚按弱，则转为肺死脏之候。又因肺金易受他脏乘侮，原文以四脉辨邪：浮大而洪为心火克金之贼邪，大而缓为脾土归子之虚邪，沉濡而滑为肾子乘母之实邪，弦细为肝木乘肺之微邪（原文虽未全引，然四者并列）。诸类以平脉为常，死脉为极，贼邪最逆，虚邪最轻，实邪自愈，共同构成以肺金为中心、以五行生克为纲的脉病机体系。", "c": [{"name": "主肺平", "desc": "微涩短为秋金肺旺之平脉。原文'秋金肺旺，其脉微涩而短曰平'，微为肺气收敛，涩为金性肃降，短为秋脉应时，三者合为肺脏无病之常象，故主肺之平调。"}], "n": {"主肺平": 1}, "a": {"21609": "主肺平"}, "t": 1, "np": 0}, "c:细+沉+浮+虚": {"o": "沉细浮虚脉总主阳虚阴寒之证。沉细为阳气虚衰、寒凝脉道，浮虚无力为虚阳外浮而内真寒，二者皆以无力为共征，反映阳气不足、阴寒内盛之本质。所主病机可归为三类：阳虚寒凝、虚阳外浮、阴寒厥逆，三者相互关联，阳虚寒凝为基本病机，虚阳外浮为阳虚之变局，阴寒厥逆为阳虚寒盛之危重阶段。原文以附子为阴证要药，凡见此脉之伤寒阴证、中寒夹阴，虽身热亦须附子温救，甚则急用生附，可见此脉所主总不离阳气衰败、阴寒用事，为临床辨识阴证之关键脉象。", "c": [{"name": "主阳虚寒凝", "desc": "沉细为阳气虚衰、寒邪内凝，脉道不充。原文以沉细定附子所主之阴证，谓其能补命门、救阳虚，除心腹腰膝冷痛，正合阳虚寒凝之机。"}], "n": {"主阳虚寒凝": 1}, "a": {"26080": "主阳虚寒凝"}, "t": 1, "np": 0}, "c:数+虚+洪": {"o": "洪数虚脉总起来主正气已虚而邪热内扰之候。其脉洪数为阳热之象，虚为不足，合而观之，非实火亢盛，乃虚阳外浮、真阴亏虚，或郁火内灼、暑热弥漫。所主病机可归纳为虚火、虚损、郁火、暑热、疟、痰六类：虚损为根本，因劳倦、入房、饥寒等致正气先亏；虚火由阴亏而生，内动为患，上炎则作渴，灼肺则咳嗽面白；郁火多因肝脾郁结，化火灼阴，左关尤甚；暑热为外邪乘虚内扰，或温补助热，迫血下漏；疟为邪蕴少阳，久成疟疾；痰由肾虚不能摄水归源而致。诸类之间，虚为共性，热为标象，虚火、郁火、暑热、疟、痰皆可因虚而生，故治多从补虚清火、健脾调肝入手，不可概作实热。", "c": [{"name": "主虚火", "desc": "洪数而虚，洪数为阳热之象，虚为不足，乃虚阳外浮、真阴不足之候，非实火也。如薛案六脉洪数而虚，断为肾经亏损、虚火上炎；许案脉数而洪属虚火，火胜金伤。虚火内动，故脉虚数。"}, {"name": "主虚损", "desc": "脉虚豁散数，为气阴两伤、正气已亏之征。如震按所凭在脉虚豁，虽外证似伤寒，仍作虚证治；劳后入房感风，正气先亏，脉见虚数。虚损为本，故脉虚而数。"}, {"name": "主郁火", "desc": "洪数为火郁，虚为气血不足，左关尤甚则肝火偏亢。如妇人腹内结块渐大、经水不调、内热作渴，脉洪数而虚，左关尤甚，断为肝脾郁结、郁结化火，灼伤阴血，故脉虚数。"}, {"name": "主暑热", "desc": "洪为热盛，数为邪热，不清示热邪弥漫、阴液受灼。如疟痢并作，面垢苔黄，干呕口渴，溺赤汗出，脉洪数不清，属暑热壅盛；或吸受暑邪，温补助热，迫血下漏，脉洪而数。"}], "n": {"主虚火": 3, "主虚损": 1, "主郁火": 2, "主暑热": 2}, "a": {"3282": "主虚火", "3333": "主虚损", "4017": "主郁火", "13716": "主虚火", "14115": "主暑热", "14177": "主暑热", "14840": "主虚火", "24055": "主郁火"}, "t": 8, "np": 0}, "pc:右+数+弦+细": {"o": "右·数弦细脉总属阴虚火旺、肝郁化火、痰热内蕴、脾虚湿滞、气液两竭与风阳上扰之候。其基本脉象为弦、细、数，弦主气郁肝旺，细主阴血亏少，数主火热内炽，三者相合，反映阴亏于下、火亢于上、气郁于中的复杂格局。若兼滑、濡，则痰湿内蕴、脾运失司；若兼虚、弱、空，则气液耗竭、正虚邪恋；若风阳升动，则见眩晕耳鸣。诸类之间相互关联：阴亏为本，火旺为标，火灼津液则成痰，木旺克土则生湿，久病则气液两伤。故其病机虽繁，总以阴虚火旺为核心，兼夹痰、湿、风、郁为患，属半虚半实、本虚标实之证。", "c": [{"name": "主肝郁化火", "desc": "弦为肝木偏旺、气机郁滞，数为火象，细为郁火灼阴。原文谓'肝家有火''肝木犯胃''肝阳易动'，木火刑金则咳嗽，犯胃则脘痛。如'肝家有火，肺胃之痰纠结不清'，'阴虚生风'，'右弦主肝气偏亢'，均示肝郁化火之机。"}, {"name": "主痰热内蕴", "desc": "滑为痰湿，数为热，弦为气郁，细为阴伤，合示痰热互结、阴液受灼。原文见'痰带粉红色''搏液成痰''痰浊壅盛'，右寸关滑大，寸滑如珠，弦滑而空，皆痰热内蕴之征，兼细数则阴伤火旺。"}, {"name": "主脾虚湿滞", "desc": "右脉濡滑、弦细带数，濡主湿，弦主郁，数主热，细主阴亏。原文谓'湿热留恋募原，三焦宣化失司，脾不健运'，纳少溲赤、苔薄黄、多日未更衣，'气虚生湿''湿随气陷'，皆脾虚失运、湿郁化热之候。"}, {"name": "主气液两竭", "desc": "脉弦细数而兼空、弱、虚，空为气液耗竭，弱为气衰，虚为不足。原文'气液两竭，热毒逗留'，'右脉细数微弱'，'半虚半实'，皆正虚邪恋、气阴两伤之象，细数示阴亏热炽，弦示余邪未清。"}, {"name": "主风阳上扰", "desc": "弦为肝风内动，数为火升，细为阴亏，风阳上冒则耳鸣、头晕、肢麻。原文'阴虚生风，风从上扰，两耳鸣响'，'风阳内炽'，'肝木偏旺'，皆水不涵木、风阳上扰之机，脉弦细数并见。"}], "n": {"主肝郁化火": 1, "主痰热内蕴": 1, "主脾虚湿滞": 1, "主气液两竭": 2, "主风阳上扰": 3}, "a": {"384": "主脾虚湿滞", "7397": "主气液两竭", "9119": "主风阳上扰", "10479": "主肝郁化火", "11459": "主痰热内蕴", "13019": "主风阳上扰", "13208": "主气液两竭", "14562": "主风阳上扰"}, "t": 8, "np": 0}, "c:浮+涩+短": {"o": "浮涩短脉总起来以肺金之象为根基：浮应肺位至高，涩短应肺气收敛，故首为秋令肺金平脉。然同一脉象因兼脉、兼症与色脉相参之异，可主多类病机。其一为常，即肺平脉；其二为肺燥失制，金不制木而肝越离魂；其三为虚损危候，阴伤阳浮、血少气衰，浮数短涩并见两寸极小；其四为脏气衰绝，兼怪脉无胃气则主死；其五为色脉逆顺之辨，据五行生克判吉凶。各类之间以肺金收敛之性为枢：常则收敛自如，病则或燥而失敛、或虚而浮越、或衰而绝无胃气，皆从浮涩短之象推衍其阴阳虚实与预后顺逆。", "c": [{"name": "主肺燥肝越", "desc": "肺燥失其相傅之权，金不制木，肝木无所畏制而飞扬上越，魂不能藏，名离魂。原文见肝脉浮濡、肺脉沉数，反肺脉当浮短而涩之常，示肺燥肝越、金不制木之机，故见蒸热如焚、谵语等症。"}, {"name": "主脏气衰绝", "desc": "脉病人不病而见屋漏、雀啄、弹石、解索等怪脉者死，皆无胃气柔和之象。浮涩短若兼此类怪脉，示脏气衰绝、胃气已败，预后凶险。原文列诸怪脉以候死生，说明脉失冲和、脏气竭绝则危。"}], "n": {"主肺燥肝越": 1, "主脏气衰绝": 1}, "a": {"17361": "主肺燥肝越", "18621": "__np", "19372": "__np", "21823": "主脏气衰绝", "26609": "__np"}, "t": 5, "np": 3}, "c:数+滑+缓": {"o": "缓滑数脉总起来主痰湿与热相合为患，其病机核心为痰湿内蕴、湿热痰滞，或痰火痹结。缓主湿滞，滑主痰湿，数主热。若脉缓滑不数，则热势不炽或已退，而痰湿仍盛；若脉滑数，则痰火痹结。各段均围绕痰湿与热的不同程度展开：或湿温之邪郁于血分，或湿热痰滞阻于肺胃，或痰火痹结经络。治疗上或清营泄卫，或降气化痰，或清泄通降，总以化痰祛湿、清解余热为要。脉象的动态变化（如滑数转缓）可反映邪热消退而痰湿未清，故辨证需结合脉症，分清痰、湿、热之偏重。", "c": [{"name": "主痰湿内蕴", "desc": "脉缓滑不数，缓为湿滞，滑为痰湿内蕴。如案中体肥多湿，湿得热而蒸痰，痰阻肺胃，见痰多干呕、胸闷等症。脉滑主痰，缓主湿，故缓滑脉多提示痰湿内盛，阻滞气机。"}, {"name": "主热势已退", "desc": "脉缓滑不数，不数则热不炽。原文多次以“不数”判断热退，如“是热且退矣”“热不炽”。数脉主热，今不数而缓滑，说明邪热已减，病势向愈，但痰湿未清。"}, {"name": "主痰火痹结", "desc": "初诊脉滑数，为痰火痹结；经开结通痹后“脉之滑数亦缓”，滑数主痰火，缓则邪势退，证明病本为痰火痹结。痰火内结，阻滞经络，故脉滑数，治以清泄通降。"}], "n": {"主痰湿内蕴": 1, "主热势已退": 1, "主痰火痹结": 1}, "a": {"745": "主痰湿内蕴", "10902": "主痰火痹结", "14647": "主热势已退"}, "t": 3, "np": 0}, "c:数+弦+疾": {"o": "弦数疾脉总起来主邪热炽盛、郁结于内、阴液耗伤之病机。弦为邪郁，数疾为热极，三象并见，示邪热鸱张而郁结不散，热盛则阴伤，甚则内闭心包或引动肝风。其具体所主，可因邪之部位与兼症不同而有所偏重：或热陷营阴、内闭心包（如）；或邪热炽盛、阴液耗伤、肝风内动（如）；或疟邪郁于少阳、热多寒少（如）。各类之间以“热盛”为核心，邪郁为热盛之因，阴伤为热盛之果，疟邪郁少阳则为热盛之特殊病位。数疾微弦脉又可见于失血后营血大伤、脾阳不振、痰浊阻壅之虚实夹杂证，然其总不离热与郁、虚与实之交错。", "c": [{"name": "主热盛", "desc": "弦数疾脉中数疾为热极之象，主邪热炽盛、热势鸱张。原文如热陷营阴、昏狂谵语，燥热非常、人事昏沉，皆因热邪内燔，鼓动血脉，故脉数疾；弦为邪郁，热与邪结，故弦数疾并见，总属热盛之候。"}, {"name": "主邪郁营阴", "desc": "弦主邪郁，数疾为热灼营阴。原文先厥后热、逆入营阴、白㾦虽露而营邪郁遏不宣，脉弦数疾，示邪热郁于营分，不得外达，有闭厥之虞。弦象反映邪气郁结，数疾反映营阴受灼，故主邪郁营阴、内闭心包之机。"}, {"name": "主疟邪郁少阳", "desc": "原文论疟脉自弦，弦数者多热，弦为少阳邪郁之象，数主热。疟邪伏于少阳，与正气相争，故脉弦；热邪偏盛则数。弦数疾脉在此主疟邪郁于少阳、热多寒少之病机，为疟病常见脉象之一。"}], "n": {"主热盛": 1, "主邪郁营阴": 1, "主疟邪郁少阳": 1}, "a": {"2467": "主邪郁营阴", "10393": "主热盛", "21973": "主疟邪郁少阳"}, "t": 3, "np": 0}, "pc:右+数+弦+浮": {"o": "右·数弦浮脉总起来主风热外袭、风阳内动与燥伤肺津、虚实错杂之候。浮为邪在表、气逆，数为热，弦主风动与木旺郁滞，右寸独见则病位偏于上焦肺卫。三段原文所示：一为暑风新感，浮数示外邪化热、弦示风动；二为辛甘温燥致风阳内煽，左脉浮弦且数，见胁跳、胸痒、汗出、不眠；三为肺伤于燥、治节不行，右脉软滑而虚，津液被烁。诸类之间，外感风热为邪实之始，风阳内动为热化风生之变，燥伤肺津为液亏之本，虚实错杂则贯穿始终——浮数弦属邪热风动之标，软滑虚属津亏脾弱之本，故临证须辨标本虚实，不可单纯作痰嗽或外感论治。", "c": [{"name": "主外感风热", "desc": "右寸弦浮数，浮为邪在表，数为热，弦主风。原文断为「上焦暑风，因新感风寒引起」，是浮数示新感外邪化热，弦示风动，右寸独见说明病位在上焦肺卫，故主外感风热、邪郁肺卫之候。"}, {"name": "主风阳内动", "desc": "左脉浮弦且数，因温以辛甘，致风阳内煽。浮弦为风阳浮动之象，数为热，合之见左胁跃跃跳动、胸次痒如虫行、嗽甚则汗、夜不安眠，皆风阳内扰、液亏风动之征，故主风阳内动、肝木亢盛。"}], "n": {"主外感风热": 1, "主风阳内动": 2}, "a": {"7223": "主外感风热", "13364": "主风阳内动", "13890": "主风阳内动"}, "t": 3, "np": 0}, "c:弦+洪+芤": {"o": "弦洪芤脉总起来主热亢阴虚、肝阳偏亢、迫血妄行之病机。其中洪脉主热盛，为邪热亢盛、气血涌盛之象；弦脉主肝阳亢逆，因肝阳偏亢、气火上升而脉气紧张；芤脉主阴血亏虚，因阴血耗损、脉道不充而中空。三脉并见，则示热盛与阴伤并存，即原文所谓‘热亢阴虚’、‘热实阴虚’。热盛可灼阴，阴亏可致阳亢，阳亢又助热势，形成恶性循环，终致热迫血溢而见鼻衄。面黑黯而有红光，为阴虚火旺、虚阳上浮之征。故本脉总以热盛、阳亢、阴伤为三大病机要素，三者相互交织，而以热亢阴虚为核心。", "c": [{"name": "主热亢阴虚", "desc": "弦洪芤三脉并见，原文总括为‘热亢阴虚之证’、‘脉情为热实阴虚’。热盛（洪）与肝阳亢（弦）合为热实，阴血亏虚（芤）为阴虚，热迫血溢而鼻衄，面黑黯有红光为虚阳上浮，诸脉合参，主热亢阴虚、迫血妄行之病机。"}], "n": {"主热亢阴虚": 3}, "a": {"13398": "主热亢阴虚", "14167": "主热亢阴虚", "14461": "主热亢阴虚"}, "t": 3, "np": 0}, "c:弦+紧+迟": {"o": "弦迟紧脉总属阴寒内盛、气滞血凝之证。迟主寒，紧主痛，弦主气机郁滞，三脉相合，反映寒邪内侵、阳气受困、气血运行不畅的核心病机。其所主病机可归纳为寒、痛、阳虚、气滞、血寒五类，彼此关联：寒邪为致病之主因，寒性收引凝滞，导致气机郁滞；气滞则血行不畅，形成血寒凝滞；寒凝气滞，不通则痛；若阳气素虚，则寒从内生，阳虚失于温煦，更助寒凝。原文湿温匝月，苦寒伤阳，邪陷少阴厥阴，脉左弦迟而紧，右沉细无力，示寒湿瘀滞兼阳衰；小产后中虚血寒，脉迟紧带弦，示中焦虚寒、血分凝滞。故弦迟紧脉总以寒为核心，涉及气、血、阳、痛等方面，临床多表现为里寒实证或虚寒证。", "c": [{"name": "主寒", "desc": "迟脉主寒，紧脉亦主寒，弦迟紧并见为阴寒内盛之象。原文述湿温匝月，苦寒叠进，邪陷少阴厥阴，脉左弦迟而紧，示寒湿瘀滞；小产后脉迟紧带弦，为血寒。故弦迟紧脉主寒邪内盛，或为外寒，或为阳虚生寒。"}], "n": {"主寒": 2}, "a": {"162": "主寒", "8451": "主寒"}, "t": 2, "np": 0}, "pc:双+弦+细+紧": {"o": "双弦细紧脉总主寒、虚、阳衰、痰凝诸病机。弦紧为寒凝气结，细为气血不足，弦则为减，故脉象总以寒凝阳衰为本，气血亏虚为标。寒凝则胃阳不开，阳衰则不能温运，气血不足则形体羸瘦、失精亡血，痰凝络脉则生瘰疬结核。诸类之间，寒凝与阳衰互为因果，虚损与痰凝皆由阳气不振、气血不充所致。治当温阳散寒、通补胃阳、复阳生阴，使阳气得通、阴血渐复，则寒减脉和，痰核自消。", "c": [{"name": "主寒凝", "desc": "弦紧为寒，寒性收引凝滞，故脉见弦细而紧。原文谓“弦则为减，紧则为寒”，又言“双弦者寒也”，寒凝气结则胃阳不开，治以通补胃阳或小建中汤温阳散寒。"}], "n": {"主寒凝": 2}, "a": {"5311": "主寒凝", "5345": "主寒凝"}, "t": 2, "np": 0}, "pc:寸+数+滑+微": {"o": "寸·数滑微脉总起来主痰热内阻、气逆不降与络脉痹阻。滑数之象反映痰热胶结，寸溢反映气机上逆，弦滑反映痰凝络痹。三者相互关联：痰热为病之本，痰热内阻则气机不畅而气逆，气逆日久则血行不利而络痹，故临床可见经断乳少、胁痛、嗽痰带血等症。此脉以痰热为核心，气逆与络痹为痰热所致之变，共同构成痰热阻络、气逆不降之病机格局。", "c": [{"name": "主痰热", "desc": "脉滑而微数，滑为痰，数为热，故主痰热内阻。原文'关尺滑而微数'及'滑数主痰热'明言痰热胶结，阻于阳明，致经断乳少、嗽痰带血，为痰热为患之征。"}], "n": {"主痰热": 2}, "a": {"13296": "主痰热", "13813": "主痰热"}, "t": 2, "np": 0}, "pc:寸+数+细+滑": {"o": "寸·数细滑脉总主痰热内蕴、阴液受伤、邪郁气结之复合病机。数主热，滑主痰，细主阴伤，三者相合，反映热蒸灼液、湿蕴生痰、痰热郁于心胸而阴津已损的病理状态。原文以'细为阴伤，滑数为痰热'为纲，指出邪留恋不化，郁于心胸，湿蕴生痰，热蒸灼液，故见烦躁、恶心、错语，舌边乾红、苔黄腻。脉象又示'将燥未燥，将陷未陷'，提示阴亏之体，邪热有内陷之虞。各类病机相互关联：痰热为病之标，阴伤为病之本，邪郁为病之枢，内陷为病之变。痰热不化则阴伤愈甚，阴伤则邪易内陷，故临证需兼顾清热化痰、养阴透邪，以防内陷之危。", "c": [{"name": "主痰热", "desc": "脉滑数并见，滑主痰，数主热，原文谓'湿蕴生痰，热蒸灼液'，痰热郁于心胸，故见烦躁、恶心、错语，舌苔黄腻。此脉象直接反映痰热内蕴之病机。"}], "n": {"主痰热": 2}, "a": {"13524": "主痰热", "14578": "主痰热"}, "t": 2, "np": 0}, "pc:六+弦+急+长": {"o": "六脉弦急长脉总起来主实邪壅滞、气逆上攻与痰浊胶结。弦长劲急为实邪内壅、气机亢逆之象，故见冷气满腹、大痛拥上；两畔细脉沸然如烂绵，则为痰浊胶结、脉道不利之征。三者相互关联：实邪壅滞为病之本，气逆上攻为病之势，痰浊胶结为病之形。原文断为胸膈臭痰，投滚痰丸取效，正说明弦劲主实、细绵主痰，实邪与痰浊相合为患。故本脉所主，以实邪痰浊为核心，气逆为标，属实证、痰证范畴。", "c": [{"name": "主实邪壅滞", "desc": "弦长劲急为实邪内壅、气机不畅之象。原文'六脉弦长劲急'，断为'实邪壅滞'，故见冷气满腹、大痛不堪、痛阵拥上等症，皆因实邪阻滞、气逆上攻所致。"}], "n": {"主实邪壅滞": 1}, "a": {"3845": "主实邪壅滞"}, "t": 1, "np": 0}, "c:微+涩+短": {"o": "微短涩脉总起来主气血亏虚、血少瘀滞及正虚瘀结之候。微为气弱，短涩为血少气滞，三象合见，反映正气不足与瘀血内结并存。原文妇人因家贫多劳、性急，耗伤气血，又致瘀血内结，出现经断、腹块、肿胀、食减、发热等症，脉微短涩，左尤甚，左主血，故血瘀偏著。其病机核心为正虚邪结：气血两虚为本，肝郁气滞为因，血瘀成积为果，胃气不足为兼。四类病机相互关联，虚、郁、瘀、积交织，然胃气尚存则生机未绝，故虽危犹可图治。", "c": [{"name": "主气血两虚", "desc": "脉微为气弱，短涩为血少，故主气血亏虚。原文'面白形瘦'、'饮食减四之三'，显系气血不足之象；脉微短涩并见，正是气血两虚、脉道不充之征。"}], "n": {"主气血两虚": 1}, "a": {"3968": "主气血两虚"}, "t": 1, "np": 0}, "c:弦+紧+长": {"o": "弦紧长脉总起来主肝郁寒凝、气滞邪实，本于肝病而累及他脏。弦主肝郁，紧主寒痛，长主气滞邪实，三象合见，提示肝气郁结、寒邪凝滞、气机壅塞、邪实有余。其病机核心在肝：肝郁日久，气机不畅，则脉弦；寒凝经脉，拘急疼痛，则脉紧；邪实内结，气滞不通，则脉长。肝病及脾，木克脾土，则见十年不食、阳明空虚；肝风内动，则闻声痉厥、终夜抽搐。诸类病机相互关联：肝郁为始，寒凝、气滞为继，邪实为果，木克脾土为传变。故弦紧长脉虽主多端，总不离肝郁寒凝、气滞邪实，本脏自病而累及脾土，属邪实有余之候。", "c": [{"name": "主肝郁", "desc": "弦脉为肝郁之象，原文谓‘弦主肝郁’。患者初因肝郁胁痛，继而肝厥犯胃，六脉弦紧而长，弦象显著，反映肝气郁结、疏泄失常，气机不畅，故以弦脉为主肝郁。"}], "n": {"主肝郁": 1}, "a": {"5263": "主肝郁"}, "t": 1, "np": 0}, "pc:六+滑+大+洪": {"o": "滑大洪脉总起来主热、湿、痰及水亏火盛之候，其核心病机为热邪充斥、湿痰壅滞与阴虚火旺相互夹杂。洪大主热盛，滑主湿痰，二者相合多示湿热痰浊壅阻阳明，脉道充盈而现洪大滑利，如湿热痿证；若兼浮象，则又反映水亏火盛、虚火上炎，洪大虽为热势外扬之标，其本却在少阴水亏不能制火。可见此脉所主非单纯实热，亦非纯虚无邪，而是实热、湿痰与阴虚火旺交织，虚实夹杂。临证须结合兼症辨别标本：湿热壅盛者当从阳明论治，水亏火旺者当滋水制火，不可一味补阴或清热，以免助湿或伤正。各类病机之间以热为核心，湿痰为其壅滞之形，水亏为其根本之因，共同构成滑大洪脉的复杂主病格局。", "c": [{"name": "主湿热", "desc": "脉洪大而滑，洪为热盛，滑主湿痰。原文见六脉洪大而滑，伴腰酸腿软、不能跪拜、间有腰痛，前医补阴反日重一日，说明非虚乃湿热下注、痿躄之候。湿热壅于阳明，脉道充盈，故现洪大而滑，与诸痿独取阳明法相应。"}], "n": {"主湿热": 1}, "a": {"5441": "主湿热"}, "t": 1, "np": 0}, "pc:尺+数+弦+大": {"o": "尺·数弦大脉在古籍中仅见一例推论，其核心病机为肝经火热内郁。弦主肝，大主阳亢，数主热，尺部候肾与下焦，故脉象组合指向肝肾火旺。此脉所主病机单一，即肝火内郁，未见其他类别。总述：该脉总起来主肝火亢盛，病位在下焦肝肾，病性属热。弦大数为阳热之象，提示肝阳偏亢、火热内郁，治当清泻肝火。", "c": [{"name": "主肝火", "desc": "关尺候肝肾，弦大为肝阳亢盛，数为热象，合而提示下焦肝肾火旺。原文虽未直接诊得脉象，但据证推脉，认为关尺想必弦大且数，病机属肝经火热内郁。"}], "n": {"主肝火": 1}, "a": {"5959": "主肝火"}, "t": 1, "np": 0}, "pc:左+滑+大+涩": {"o": "左·滑大涩脉总起来主虚实夹杂之证。左涩主血少或血瘀，右寸关滑大主痰火壅于中上焦，两尺弱主下元虚惫。三部位脉象合参，提示上焦痰火未清、中焦脾弱、下元不足。原文吐血后咳喘、泄泻、发热烦躁，前医滋阴则泻甚、保脾则火炽，正因脉象虚实并见：痰火壅盛为实，血少血瘀与下元虚惫为虚。故本脉所主病机以痰火壅盛、血少血瘀、下元虚惫为三大类，而虚实夹杂贯穿其中，各证相互影响，形成上实下虚、虚实错杂之局。", "c": [{"name": "主血少血瘀", "desc": "左脉涩，涩主血少或血瘀。原文吐血二碗余，阴血亏耗，脉道不充则涩；离经之血留滞，脉气不畅亦涩。故左涩反映失血后阴血不足与瘀血内停并存。"}], "n": {"主血少血瘀": 1}, "a": {"6143": "主血少血瘀"}, "t": 1, "np": 0}, "c:细+坚+硬": {"o": "细坚硬脉总起来主肾经湿毒蕴结、阴血不足、病根深伏之候。脉细为阴血亏虚，左尺坚硬鼓指为湿毒久郁化热、结聚不散，二者相合，形成虚中夹实、本虚标实之象。湿毒深伏于肾，循少阴经脉上攻，故见喉间糜碎、舌下肿胀；前症淋浊、横痃下疳虽愈，而病根未除，脉象仍显坚硬鼓指。三类病机相互关联：阴血不足为病之本，湿毒蕴结为病之标，病根深伏则示邪伏少阴之深。临床见此脉，当考虑肾经湿毒久郁、阴血耗伤之复杂病机，非单纯补虚或攻邪所能尽，需兼顾虚实，深究病根。", "c": [{"name": "主湿毒蕴结", "desc": "脉细而左尺坚硬鼓指，为湿毒深伏于肾，久郁化热，结聚不散之象。原文谓‘湿毒深伏于肾’，曾患淋浊、横痃下疳，虽愈而喉间糜碎、舌下肿胀，皆肾经湿毒上攻所致，故脉象相应。"}], "n": {"主湿毒蕴结": 1}, "a": {"8048": "主湿毒蕴结"}, "t": 1, "np": 0}, "pc:右+数+弦+实": {"o": "右·数弦实脉总起来主郁热内结、枢机不利之证。数脉主热，右实主阳明热结，左弦主少阳枢机不利，三者相合，提示热郁少阳、胆胃不和，气机上逆。原文服养阴药得效未愈，见嘈杂恍惚、胸上动气，治以苦寒清热、小柴胡汤和解枢机，脉证相应。各类病机相互关联：热郁为因，热结阳明与枢机不利为不同病位表现，气机上逆为继发结果，共同构成少阳阳明合病、郁热内扰之病机整体。", "c": [{"name": "主热", "desc": "脉数主热，原文明言‘数主热’，且‘苦寒清热’佐证热邪存在。热郁少阳，胆胃不和，故脉数。"}], "n": {"主热": 1}, "a": {"8636": "主热"}, "t": 1, "np": 0}, "c:细+大+小": {"o": "细小大脉在此段中主正虚邪陷与邪伏深沉两类病机。脉细小不大，总因正气衰微，无力抗邪，致温邪不从表达，直陷厥少，邪伏深沉。正虚与邪陷互为因果：正虚则邪易内陷，邪陷又进一步耗伤正气。原文‘险如朝露’示其危重，脉细小正是正气无力托邪外出之征，故临床见此脉多属正不胜邪之危候。", "c": [{"name": "主正虚邪陷", "desc": "脉细小不大，为正气衰微之象。温邪不从表达，直陷厥少，正不胜邪，无力托邪外出，故脉细小。原文谓‘正气衰微、邪陷深沉’，险如朝露，正虚邪陷之危候。"}], "n": {"主正虚邪陷": 1}, "a": {"9412": "主正虚邪陷"}, "t": 1, "np": 0}, "pc:右+弦+大+软": {"o": "右弦大软脉总起来主肝脾不调、湿热内蕴、阴分不足之证。右脉软主脾虚湿困，左脉弦大主肝木偏旺，弦大见于阴薄之体又示阴分不足。脾虚生湿，肝旺乘脾，湿郁化热，形成肝脾不调、湿热内蕴的复杂病机。四类病机相互关联：脾虚为本，肝旺为标，阴亏为体，湿热为果。脉象右软左弦大，正是虚实夹杂、本虚标实之候，故治疗须速为清理，兼顾肝脾，清利湿热，护阴为要。", "c": [{"name": "主脾虚湿困", "desc": "右脉软，软为虚象，右部候脾，故主脾虚。脾虚运化失职，水湿内停，则见湿困。原文‘右脉软为脾虚湿困’，伴便溏、肠胃湿热，说明脾虚为本，湿浊内蕴为标。"}], "n": {"主脾虚湿困": 1}, "a": {"9869": "主脾虚湿困"}, "t": 1, "np": 0}, "pc:左+沉+涩+小": {"o": "左脉沉涩小，总属虚实夹杂之候，以肝肾阴亏为本，气机不利为标，并见肝木犯胃之兼象。沉小主阴精亏虚，涩主阴血不足、气行不畅，弦则示肝旺制中。三者相合，反映阴亏于下、气滞于中、肝逆于上的病机格局。因阴亏而肝失柔养，肝旺则犯胃，胃气失和则气机更滞，故治疗既忌香燥破气，又当养肝肾以纳气机、养肺胃以舒气化。各类之间以阴亏为根，气滞、肝逆为继发，相互影响，形成虚实兼夹之态。", "c": [{"name": "主肝肾阴亏", "desc": "脉沉小而涩，沉小为阴液不足、肝肾亏虚之象，涩主阴血亏少、脉道不充。原文明言“沉小为肝肾阴亏”，故左脉沉涩小首主肝肾阴精亏虚，阴不涵阳，本元不足。"}], "n": {"主肝肾阴亏": 1}, "a": {"12522": "主肝肾阴亏"}, "t": 1, "np": 0}, "c:数+小+急": {"o": "小数急脉总属正虚邪盛、邪热内郁之候。数急主邪热亢盛，小主正气不足，二者相合，形成正虚不能敌邪、邪热郁而不达的复杂病机。其核心在于正虚邪陷，既有邪热内郁之实，又有正气亏虚之虚，病情多危重，易生变证。下属微小数急脉更具体地反映了虚损与邪盛夹杂，以正虚为主，兼见邪热，甚则阳气衰微、阴血亏虚。各病机类别相互关联：邪热内郁是病邪方面，正气不足是体质方面，正虚邪陷则是二者交互作用的结果，提示治疗需兼顾扶正与达邪。", "c": [{"name": "主邪热内郁", "desc": "数急脉主邪热亢盛，热郁于内，鼓动血脉急迫。原文'左脉小数急'，并明言'数急为邪热内郁'，说明邪热结聚，不得外达，故脉数急。"}], "n": {"主邪热内郁": 1}, "a": {"14608": "主邪热内郁"}, "t": 1, "np": 0}, "c:数+弱+缓": {"o": "数弱缓脉总属脾虚气郁、郁热内扰之候，以脉数而弱为核心特征。数主郁热，弱主脾伤气弱，二者并见，反映忧思伤脾、气郁化热之病机。若经补脾散郁，脉转稍缓而健，则示胃气渐复、中气渐振、郁热渐退，为病势向愈之兆。三类病机相互关联：脾虚气郁为病本，郁热内扰为病标，中气渐复为转归，共同勾勒出数弱缓脉从病发到向愈的动态演变过程。", "c": [{"name": "主脾虚气郁", "desc": "脉数而弱，数因郁热，弱因脾伤气弱。原文载孀居忧思伤脾，气郁化热，故脉数弱并见，治以补脾散郁，佐证此脉主脾虚气郁、郁热内生之病机。"}], "n": {"主脾虚气郁": 1}, "a": {"15130": "主脾虚气郁"}, "t": 1, "np": 0}, "c:细+迟+伏": {"o": "迟细伏脉总起来主正虚，包括阴血不足与阳虚寒盛，并可导致毒邪内陷。脉沉细而耎，沉主里，细耎为阴血不足，正虚毒陷，故见疽形平塌、溃脓无多、不痛楚之阴证；继则脉迟细欲伏，迟细为阳虚，欲伏为阳气欲脱，伴面青肢冷、呕恶频频，乃阴寒内盛、阳气衰微之候。三类病机相互关联：阴血不足与阳虚寒盛均属正气亏虚，正虚则无力托毒，毒邪内陷，形成阴证疮疡。脉象由沉细而耎转为迟细欲伏，反映病情由阴血不足发展为阳气衰微，正虚逐渐加重，故治疗须温补内托，由阴转阳。", "c": [{"name": "主阴血不足", "desc": "脉沉细而耎，沉主里，细耎为阴血不足。原文见疽形平塌、溃脓无多、不痛楚，属阴证，正虚毒陷，故脉细耎反映阴血亏虚、正气不足。"}], "n": {"主阴血不足": 1}, "a": {"15384": "主阴血不足"}, "t": 1, "np": 0}, "pc:左+浮+小+芤": {"o": "左浮小芤脉总属虚候，以血虚为核心，兼见气亏。浮为阳浮不敛，小为脉道细少，芤为中空失血，三者合参，主阴血亏虚、脉道不充。原文见于新产之后，与右脉虚大无力并见，明示气血两亏；血少不能上荣，则清窍失养而头痛。故其病机以血虚为主，气亏为伴，清窍失养为果，三者相互关联，总归气血并亏、虚多实少之候。", "c": [{"name": "主血虚", "desc": "左脉浮小而芤，浮为阳浮，小为血少，芤为中空，三者相合，明示阴血亏虚，脉道不充。原文谓“浮小芤为血少”，且见于新产之后，气血两亏，故主血虚。"}], "n": {"主血虚": 1}, "a": {"15851": "主血虚"}, "t": 1, "np": 0}, "c:细+软+迟": {"o": "细软迟脉总主脾土虚弱、阳气不运，并常兼肝木乘土之机。细软为脾虚气血不足，迟为阳气不运，故右脉见之，主脾胃虚寒、运化失职。然此案左脉沉小弦，示肝阴不足而肝气偏旺，合之素有肝胃气、胀痛兼呕，则土虚木乘、肝胃不和之病机昭然。三类病机相互关联：脾虚为本，阳运不健为虚寒之因，土被木乘为虚实夹杂之果。总以脾胃虚弱、阳气不运为核心，兼见肝气偏旺乘脾之象。", "c": [{"name": "主脾虚", "desc": "右脉细软，细为气血不足，软为脉道松弛，主脾土虚弱。原文谓“细软为脾土虚弱”，且伴食入即胀、胀则欲卧，乃脾胃运化无力之象。"}], "n": {"主脾虚": 1}, "a": {"15972": "主脾虚"}, "t": 1, "np": 0}, "pc:左+细+涩+空": {"o": "左·细涩空脉总属阴血亏虚、肝失濡养、虚风内动之候。细主阴血不足，涩主血少，空为营阴亏虚，三脉并见，提示心肾阴亏为病之本。阴血亏虚，肝木失涵，进而风阳窃动，出现四肢麻木、形容不泽等症。三类病机以阴血亏虚为核心，肝失濡养为中间环节，虚风内动为发展结果，层层相因，治当乙癸同源、滋水涵木。", "c": [{"name": "主阴血亏虚", "desc": "脉细涩而空，细主阴血不足，涩主血少，空为营阴亏虚。原文谓'心肾阴亏'，阴血不能充盈脉道，故脉细涩而空。此为本脉最直接病机，阴血亏虚贯穿诸症。"}], "n": {"主阴血亏虚": 1}, "a": {"18125": "主阴血亏虚"}, "t": 1, "np": 0}, "pc:寸+数+滑+实": {"o": "寸·数滑实脉总主宿食内停、邪实于中。数主热，滑主食，实主邪盛，故其核心病机为食积化热、胃气壅实。由此可衍生三类相关病机：一是胃气不降，食阻中焦而见痛、吐、不能食；二是寒热如疟，食积与正气相争而寒热交作；三是风寒头痛，寸脉紧示外寒与宿食相兼。四类均围绕“宿食内实”展开，或为食积本身，或为食积所致气逆、寒热、外感兼夹，总属邪实有余之候，故原文有“当吐之”“下之愈”之治。", "c": [{"name": "主宿食内实", "desc": "脉数滑实，数主热，滑主食积，实主邪盛。原文“脉数而滑者实也”明指宿食内停、郁而化热、邪实于中，故可下之。"}], "n": {"主宿食内实": 1}, "a": {"21555": "主宿食内实"}, "t": 1, "np": 0}, "c:大+虚+散": {"o": "虚大散脉总属虚候，主气阴两伤、元气欲脱。其脉虚大无根、欲散不收，为阴液亏极、脉道失充，元气将脱、虚阳浮越之象。原文于加减复脉汤中加人参，益气固脱、生津复脉，正针对气阴两伤、虚阳欲散之病机。两类病机相互关联：阴液亏极可致元气无所依附而欲脱，元气耗散又加重阴液不守，故临床多气阴两伤与元气欲脱并见，属虚实夹杂之危重证候。", "c": [{"name": "主气阴两伤", "desc": "脉虚大欲散，虚为阴液亏极，大为脉道失充而浮大无根，欲散为元气将脱之兆。原文于加减复脉汤中加人参，益气固脱、生津复脉，正对气阴两伤、虚阳欲散之机。"}], "n": {"主气阴两伤": 1}, "a": {"24484": "主气阴两伤"}, "t": 1, "np": 0}, "pc:六+细+涩": {"o": "六·细涩脉总起来主阴血亏虚、气滞血瘀，并可兼见脾肾虚败、肾虚不摄、正虚络痹及营亏痰凝等证。细为阴血不足，涩为血行不畅，二者相合，根本空虚而气血运行涩滞。各段所主虽异，然皆不离‘虚’与‘滞’两端：或阴血亏少而脉道不充，或气滞血瘀而脉行不畅，或脾肾虚败而胃气衰败，或肾虚不摄而根本空虚，或正虚络痹而气血不达，或营亏痰凝而形伤及气。其病机演变多由虚致滞，由滞致损，虚实夹杂，故临床见细涩脉当细辨虚、滞、痰、瘀之偏重。", "c": [{"name": "主阴血亏虚", "desc": "细主阴血不足，涩主血行不畅。原文多述‘六脉细涩’伴面淡黄、舌白、经事愆期、纳谷甚少、血液枯燥、大便不解等，皆阴血亏少、肠道失润或冲任不充之征。脉细涩正示营血虚少，不能充盈脉道。"}, {"name": "主气滞血瘀", "desc": "涩主气滞血瘀，细主血虚。原文见‘癸来腰腹联痛如刺’、‘脘中胀闷’、‘气滞脘闷，腰胯胀’等，刺痛、胀闷为气血瘀滞不通之象。脉细涩示血虚而气行不畅，瘀滞内生，冲任或中焦气机受阻。"}, {"name": "主脾肾虚败", "desc": "细为阴血亏少，涩为血行不畅，按之无神则胃气衰败。原文述吐血频年、脾土虚极不能统摄、大便作泻，脉‘六脉细涩、按之无神’，乃脾肾两败、气血俱损之重候，预后堪忧。"}, {"name": "主肾虚不摄", "desc": "细为阴亏，涩为血少气滞。原文‘六脉细涩’见于肾阴久亏、根气失摄之痰喘，冬藏不固，春阳发泄，喘呼不能坐卧，虚阳上浮而唇焦颧红。脉细涩示根本空虚，气不摄纳，有汗脱之虞。"}, {"name": "主正虚络痹", "desc": "细为阴血不足，涩为气滞血少、脉络不畅，无力为正气虚。原文‘六脉细涩无力’伴沙气袭络、遍身苛痹、肢尖逆冷、胸喉气不展舒，乃沙毒闭阻络脉而正气已虚，气血不能充达四末。"}, {"name": "主营亏痰凝", "desc": "细为营阴亏少，涩为血行不畅。原文‘六脉细涩’见面淡黄舌白、经事愆期、纳谷甚少，情志不畅，遏壅荣行，结痰成疬，结核累累蔓延上下，溃则腐骨。脉细涩正合营亏气滞、痰凝成疬之病机。"}], "n": {"主阴血亏虚": 2, "主气滞血瘀": 3, "主脾肾虚败": 1, "主肾虚不摄": 1, "主正虚络痹": 1, "主营亏痰凝": 1}, "a": {"7525": "主肾虚不摄", "7572": "主脾肾虚败", "7825": "主阴血亏虚", "12415": "主正虚络痹", "15006": "主营亏痰凝", "16987": "主气滞血瘀", "16989": "主气滞血瘀", "17053": "主阴血亏虚", "17096": "主气滞血瘀"}, "t": 9, "np": 0}, "pc:两+弱+软": {"o": "弱软脉总属虚象，以气血不足、心肺气虚为核心，可扩展至脾肾亏虚及虚中夹滞。其脉来软弱无力，多因气血耗伤、脉道不充，或久病胜气亏虚所致。寸部软弱尤主心肺气虚，常见气满汗出、不寐、食减；两手软弱无力则主气血两虚、脾肾亏虚，见吐血、血崩、腰痛、耳鸣、小溲不禁。若虚中夹滞，脉虽软弱而不数，症见里急后重、经闭带下、痰凝气郁，为虚实错杂。若元气败绝，软弱之脉可转为散乱解索，属胃气将绝之危候。诸类以虚为本，或兼滞、或兼脱，总不离气血阴阳之损。", "c": [{"name": "主气血两虚", "desc": "软弱脉为气血不足之象，如案中屡言“软弱示气血不足”“气血亏虚之常”。患者或产后、或久病吐血血崩，气血耗伤，脉道不充，故脉来软弱无力。"}, {"name": "主心肺气虚", "desc": "两寸软弱专主心肺气虚。寸候心肺，案中疝疾外治溃烂、气随液泄，见气满汗出、不寐、食减，寸脉软弱，正合上焦气虚之机。"}, {"name": "主虚中夹滞", "desc": "脉虽软弱不数，而症见里急后重、二便疼痛、经闭带下、虚浮痰梗，属虚中夹滞、肝郁痰凝。脉软示气血不足，不数说明非纯实热，故为虚实错杂之候。"}, {"name": "主胃气将绝", "desc": "产后气血未复，脉本软弱，复因食滞怒气，吐泻交作，元气脱而脉转为散乱如解索状，神惫恍惚，循衣摸床，此胃气将绝、真元涣散之死候，软弱之脉进而败坏。"}], "n": {"主气血两虚": 1, "主心肺气虚": 2, "主虚中夹滞": 3, "主胃气将绝": 2}, "a": {"3788": "主虚中夹滞", "5987": "主胃气将绝", "6006": "主虚中夹滞", "6252": "主心肺气虚", "6281": "主胃气将绝", "6300": "主虚中夹滞", "6545": "主心肺气虚", "16553": "主气血两虚"}, "t": 8, "np": 0}, "pc:六+弦+滑": {"o": "弦滑脉总起来主肝火、痰湿、湿热、痰热及气滞血瘀化热等实邪内蕴之证，其病机核心为“火（热）与痰（湿）交结”或“气滞血瘀化热”。弦主肝郁、肝火或气结，滑主痰湿、湿热或血聚，二者相合，多示实多虚少。具体而言，或肝火挟痰上扰清窍，或相火兼湿热下注，或痰热壅肺，或气滞血瘀郁而化热，或兼阴血不足而虚实夹杂。各类之间以“火（热）与痰（湿）相合”为共同特征，但病变部位与兼邪不同，故治法有清肝化痰、清化湿热、清肺化痰、顺气活血、滋阴清肝等差异。", "c": [{"name": "主肝火挟痰", "desc": "弦为肝火亢逆，滑为痰浊内盛，弦滑不柔示肝失柔和。肝火挟痰上扰清窍，则耳鸣头晕。原文直断“肝火挟痰为患”，脉象弦滑正是火痰交炽之征。"}, {"name": "主相火湿热", "desc": "弦为相火内动、肝木不柔，滑为湿热蕴结、痰浊内盛。脉弦滑并见，说明火与湿相合，下扰精室，故见阳举精泄。原文以滋清佐苦泄法，正合脉证。"}, {"name": "主痰热壅肺", "desc": "脉弦滑而搏指，右手较甚，为痰热壅盛之实象。痰热窒肺，则渴喜冷饮、小溲如沸、夜不成眠。久服滋阴无效，因肺病治肾。投清化痰热剂而痊。"}], "n": {"主肝火挟痰": 4, "主相火湿热": 1, "主痰热壅肺": 1}, "a": {"2205": "主肝火挟痰", "2219": "主肝火挟痰", "2281": "主相火湿热", "4836": "主肝火挟痰", "7011": "主肝火挟痰", "14214": "主痰热壅肺"}, "t": 6, "np": 0}, "pc:左+弱+短": {"o": "左·弱短脉总起来主虚中夹实、本虚标实之候。其核心病机为心之气血不足（左寸短弱），但单纯虚象少见，多与痰、瘀、湿热等实邪兼夹。从所附段落看，短弱脉常与关弦大、右寸关滑大、两尺洪大数并见，形成上焦心虚、中焦痰浊、肝经瘀血、下焦湿热的复合病机。各类之间以“虚”为背景，以“痰火”“瘀血”“湿热”为标实，虚处受邪，实邪乘虚，故治疗上既需补心气心血，又当清痰火、化瘀血、利湿热，标本兼顾。", "c": [{"name": "主心虚", "desc": "左寸短弱直接反映心气或心血不足。原文多次指出“左寸短弱示心血不足”“为心气不足”“为心肺气虚”，且见于久病血淋、淋浊等耗伤气血之证，故短弱脉主心之气血虚损。"}], "n": {"主心虚": 6}, "a": {"3791": "主心虚", "4275": "主心虚", "6240": "主心虚", "6245": "主心虚", "6533": "主心虚", "6538": "主心虚"}, "t": 6, "np": 0}, "c:虚+迟": {"o": "虚迟脉总属正气亏虚、阳气衰微之候，以虚、迟两象合见为特征。虚主气血阴阳不足，迟主阳衰内寒，故其核心病机为虚寒与虚损。具体而言，虚迟脉所主涵盖：中阳不足、脾胃虚寒，运化失职；劳役内伤、营卫不和，渐成虚损；气血两亏、冲任不固，带下腰疼；阳衰寒盛、饮邪内停，翻胃吐冷；甚则阳气浮散欲脱，误汗亡阳；或正虚邪伏，本虚标实；或精血亏耗，阴阳两虚。各类病机之间以阳气虚衰为共同基础，或兼寒、兼饮、兼邪、兼血虚，然总不离虚寒二字。虚迟脉虽主虚寒，然虚芤迟等兼脉又示精血亏耗、阴阳两虚之重证，临证当细辨兼脉，以分虚实主次。", "c": [{"name": "主虚寒", "desc": "虚迟脉主阳气虚衰、阴寒内盛。虚主正气不足，迟主阳衰内寒。原文见“脉象虚迟”伴形瘦色萎、食减神疲，或“六脉虚而迟”见饮食入胃胀吐、吐出物极冷，皆中焦虚寒、运化失职之征。"}, {"name": "主虚损", "desc": "虚迟脉主劳役内伤、气血阴阳亏虚，势将成损。虚为正气不足，迟为阳气衰微。原文“劳役太过，脾胃两伤”致寒热似疟、形瘦色萎，舌光有津，脉虚迟，显系营卫不和、阳气虚馁之虚损病机。"}, {"name": "主中阳不足", "desc": "虚迟脉主中阳不振、胃气虚寒，腐熟无力。虚主气弱，迟主阳衰。原文“脉迟延虚”见瘕聚脘痛、得食则呕、苦酸痰涎、食物觉冷，翻胃半年，系中阳挟饮、火衰气郁，或胃中无火、饮食停滞而吐衄。"}, {"name": "主血虚气弱", "desc": "虚迟脉主气血两亏、冲任不固。虚为气血不足，迟为血海不充、癸水趱迟。原文“脉虚癸水趱迟”伴腰疼带下如注，乃血虚不能濡养、气虚不能固摄，冲任不约所致。"}], "n": {"主虚寒": 2, "主虚损": 1, "主中阳不足": 1, "主血虚气弱": 1}, "a": {"271": "主虚损", "8321": "主虚寒", "11673": "主中阳不足", "17108": "主血虚气弱", "18251": "主虚寒"}, "t": 5, "np": 0}, "pc:右+虚+小": {"o": "右·虚小脉总属虚证，以中气不足、脾胃虚弱为核心，涉及气血阴阳亏虚及湿滞、疟母等兼夹。其脉象虚小，虚为不足，小为阴血亏少，右部候脾肺，故主中阳不振、脾虚湿滞、气血亏虚、脾土大亏。各类之间相互关联：中阳不振可致营卫失护，脾虚湿滞则运化无力，气血亏虚多因肝脾两伤，脾土大亏久则成积。总以扶土建中、调补气血为要，兼湿滞者佐以化湿，有积块者需消补兼施。", "c": [{"name": "主中阳不振", "desc": "右脉虚小，左脉小，症见背微寒、肢冷、痰多微呕、食减不甘，为胃阳已弱，卫气不得拥护，营卫不足，非实邪。虚小示中气不足，阳弱不能温煦，故见寒象与呕痰。"}, {"name": "主脾虚湿滞", "desc": "右脉虚小，左脉虚数，症见四肢虚浮、小溲短赤、经行腹痛、腰腿酸疼，为脾虚挟湿，运化无力，湿滞内停。虚小主脾虚，湿滞则见浮肿、溲赤，肝虚血少则夜热口干。"}, {"name": "主气血亏虚", "desc": "右脉虚小，左脉虚大，经水延绵、血去过多，阴亏阳弱，肝脾两伤。虚小为阳气弱，虚大为阴血亏，血下成块，形如鱼肠，乃气血两虚，肝脾失统。"}, {"name": "主脾土大亏", "desc": "右脉虚小无力，向有三疟，年余方止，脾土大亏，食入即胀，胀时腹疼，左腹疟母成块。虚小无力为脾虚不运，气血瘀滞，久则防成单腹胀。"}], "n": {"主中阳不振": 2, "主脾虚湿滞": 1, "主气血亏虚": 1, "主脾土大亏": 1}, "a": {"851": "主中阳不振", "4427": "主中阳不振", "15880": "主脾虚湿滞", "15910": "主气血亏虚", "16018": "主脾土大亏"}, "t": 5, "np": 0}, "pc:左+软+迟": {"o": "左·软迟脉总起来主虚损之证，以阴血不足、肾阴亏虚、命门火衰、阴阳两虚及脾虚阳弱为核心。软迟之象，非实邪壅滞，乃正气亏虚、脉道不充、阳气不运所致。诸类之间，阴血虚与肾阴虚同源而异位，前者泛言阴液亏少，后者专指左肾真阴不足；命门火衰则属阳虚一端，与肾阴虚相对；阴阳两虚为二者并见之候；脾虚阳弱则侧重中焦，兼肝木乘脾。总归左软迟脉以虚为本，或阴虚，或阳虚，或阴阳俱虚，或脾虚阳弱，皆示正气不足、脉道失充、阳气不运之机。", "c": [{"name": "主阴血虚", "desc": "左脉迟软为阴血不足、脉道不充之象。如案中三载劳损，右脉数急左脉迟软，断为阴液虚，投炙甘草汤复脉救阴。迟软非寒实，乃阴血亏少、脉道失充所致，故主阴血虚。"}, {"name": "主肾阴虚", "desc": "左尺脉虚弱或细数，为左肾真阴不足、阴虚不能制火。迟软见于左尺，示肾阴亏虚、脉道不充，虚火内生。原文以六味丸补左肾真阴，故左脉迟软主肾阴不足。"}, {"name": "主命门火衰", "desc": "右尺脉迟软或沉细数欲绝，为命门相火不足、阳虚不能鼓动。迟软为阳气不运、火衰无力之征，故主命门火衰，治用八味丸温补相火。"}, {"name": "主阴阳两虚", "desc": "两尺微弱，左尺虚弱细数、右尺迟软并见，示肾中阴阳俱虚。迟软与细数同现，阴亏阳衰并存，故主阴阳两虚，治用十补丸双补阴阳。"}], "n": {"主阴血虚": 1, "主肾阴虚": 1, "主命门火衰": 2, "主阴阳两虚": 1}, "a": {"8360": "主阴血虚", "18312": "主命门火衰", "18336": "主阴阳两虚", "23196": "主肾阴虚", "23746": "主命门火衰"}, "t": 5, "np": 0}, "pc:左+数+疾": {"o": "左·数疾脉总属热盛阳亢之象。数主热，疾主阳亢，左脉候心肝，故其病机重心在心肝火旺。具体而言，或为心火独炽，离火内亢而坎水不制；或为心肝阳亢，肝火戕胃、心火烁金；或火亢水亏，阴不制阳，虚阳外浮；甚则兼夹湿温，形成火亢水亏兼湿浊弥漫之复杂局面。诸类之间以火亢为共同核心，或偏于心，或偏于肝，或涉及胃阴、肾水，总由阳热亢盛、阴液受灼所致，故预后多凶，夏令阳盛之时尤防剧变。", "c": [{"name": "主心肝阳亢", "desc": "左脉候心肝，数疾为热盛阳亢之象。原文谓左脉数疾为心肝阳亢，肝火戕胃则谷食减，心火烁金则夜热增，胃阴失降，虚阳外浮，夏令防剧。"}, {"name": "主火亢水亏", "desc": "数疾为离火内亢，软大为坎水不制、虚阳外浮。患者年逾花甲，曲运心机，阴亏火炽，兼湿温之感，脉象舌色昭示根本已败，预后凶险。"}], "n": {"主心肝阳亢": 2, "主火亢水亏": 3}, "a": {"13045": "主火亢水亏", "13614": "主心肝阳亢", "14235": "主火亢水亏", "14534": "主火亢水亏", "14723": "主心肝阳亢"}, "t": 5, "np": 0}, "pc:右+数+涩": {"o": "右·数涩脉总起来主痰瘀内阻、营热血少、肝火亢盛与肺气不降四类病机。数主热，涩主血瘀或血少，右脉候肺脾，故其核心为热郁血滞、痰瘀交阻。四类之中，痰瘀内阻与营热血少为基本病机：痰瘀阻络则涩数并见，营热未清、血行不畅亦见涩数。肝火亢盛与肺气不降为兼涉之变：痰瘀郁久化火，常兼左关弦大，示肝经气火；热郁血络、离络之血未净，则肺气不降。四类相互关联，总以热郁血滞为枢，或兼痰、或兼虚、或兼肝火、或兼肺逆，临证当脉症合参。", "c": [{"name": "主痰瘀内阻", "desc": "右脉涩数，涩主血瘀，数主有热，合见为痰瘀内阻、郁而化热。原文如“瘀血挟痰，阻于胸膈，食则作痛，痛则呕吐，右脉涩数”，“涩主瘀血，数主痰热”，皆以涩数并见示痰瘀交阻、热由郁生。"}, {"name": "主营热血少", "desc": "涩为营血不充，数为营热未清，故右脉涩数可主营分有热而阴血不足。原文“左脉涩数，右脉弦数，营血不充，肝火不静”，“脉右涩数……离络之血未净”，均以涩数示营热未清、血行不畅。"}, {"name": "主肺气不降", "desc": "右脉涩数见于咳血案，涩为血行不畅、离络之血未净，数为余热未清，热郁血络则肺气不降。“咳血较瘥，肺气不降，脉右涩数……离络之血未净”，示热郁血滞、肺失肃降，故主肺气不降。"}], "n": {"主痰瘀内阻": 2, "主营热血少": 1, "主肺气不降": 1}, "a": {"5878": "主痰瘀内阻", "10551": "主营热血少", "10713": "主痰瘀内阻", "17113": "主肺气不降"}, "t": 4, "np": 0}, "c:大+牢": {"o": "牢大脉总起来主邪实内结之实证，以寒凝、瘀血、火壅痰滞为主要病机。牢主寒主痛、坚积内着，大主邪盛有余，左脉候下焦血分，故见下焦感寒、瘀血内蓄之腹痛、血块，脉象牢大与症相符，治宜温通散瘀；若牢数大并见，则主阳火有余、火壅痰滞，治当苦降。跌仆金疮瘀血腹胀而脉牢大者，为脉证相应，主生；若见沉细，则正虚不能鼓动，脉证相逆，主死。可见牢大脉所主虽以寒瘀与火痰为不同，然皆属邪实内结、气血壅滞之候，其大脉总不离邪盛，牢脉总不离坚积，临证须结合兼脉与症情分辨寒热。", "c": [{"name": "主寒凝血瘀", "desc": "牢主寒主痛，大主邪盛，左脉候下焦血分。原文见“下焦感寒停经，腹痛不止，血块时下”“经行房劳，下焦受寒，血紫块攻”，寒客下焦，血为寒凝，瘀阻不通，故脉见牢大。"}, {"name": "主瘀血内蓄", "desc": "牢为坚积内着，大为邪实有余。原文“从高堕下及金疮内有瘀血、腹胀、脉牢大者，生”，瘀血内结、腹胀之实证与牢大脉相应，说明牢大主瘀血内蓄之实证。"}], "n": {"主寒凝血瘀": 3, "主瘀血内蓄": 1}, "a": {"15841": "主寒凝血瘀", "15842": "主寒凝血瘀", "15843": "主寒凝血瘀", "21151": "主瘀血内蓄"}, "t": 4, "np": 0}, "c:弦+结": {"o": "弦结脉总起来主气机郁滞、血行不畅之病机，其核心为弦主肝郁、主痛、主饮，结主气滞、血瘀、积滞。四段原文分别从不同角度展现：瘀血内伏者，因久病入络，瘀阻脉道而结；气郁阳衰者，肝气郁结与肾阳衰微并见，属本虚标实；气血痹阻者，胆阳不舒、肝邪用事，气血冲突而脉行歇止；酒积气滞者，湿热酒毒内蕴，积滞日久，气血不畅。四类病机虽表现各异，但均以气机郁结为始动因素，进而导致血瘀、积滞、阳衰等病理变化。弦结脉所主，既有实证之瘀血、酒积、气滞，亦有虚中夹实之阳衰、本虚标实之候，总不离“郁”与“结”二字，反映了气血运行障碍、脉道不利的共同特点。", "c": [{"name": "主瘀血内伏", "desc": "弦主痛、主瘀滞，结为血行不畅。原文见形色瘦暗、左乳下痛、按之愈痛、夜不能寐，且曾受推压，显系瘀血内伏、久病入络。脉结正是瘀阻之征，故断为瘀血成痨之根。"}, {"name": "主气郁阳衰", "desc": "左关弦结搏指为厥阴肝气郁结、脉道不利；两尺微细欲绝乃少阴肾阳衰微、根本欲脱。症见齿舌喉闭、腹痛吐蛔、肉𥆧筋惕，因肾虚水无坐镇之权，龙雷之火上浮。脉弦结与尺脉欲绝并见，提示本虚标实、气郁阳衰。"}, {"name": "主气血痹阻", "desc": "病起左胁，上及中脘，下趋少腹，脉弦结歇止。弦为肝邪用事、胆阳不舒，结与歇止为气血痹阻、冲突其间而脉行不畅。症脉相合，示胆阳不舒、肝邪犯及气血之病机，宗通则不痛之意。"}, {"name": "主酒积气滞", "desc": "酒积腹痛脉多见洪大，洪数主热，实大主积，滑大洪数乃酒湿之积。酒积内伏，脉反弦结，弦主饮主痛，结主积滞，说明湿热酒毒内蕴，气机阻滞，故脉象由洪数转为弦结，提示积滞日久，气血不畅。"}], "n": {"主瘀血内伏": 1, "主气郁阳衰": 1, "主气血痹阻": 1, "主酒积气滞": 1}, "a": {"16612": "主瘀血内伏", "18488": "主气郁阳衰", "18519": "主气血痹阻", "25072": "主酒积气滞"}, "t": 4, "np": 0}, "pc:尺+沉+涩": {"o": "尺部沉涩脉总属阴血津液枯竭、内伤虚损之候。沉主里，涩主血少津枯，合而示病在里、阴血耗损。其类有四：一主阴血枯竭，分候脏腑则心血枯、肝血竭、肾水虚、脾阴绝、胃汁干；二主精血内竭，见于女劳疸肾虚之根；三主气郁血滞，沉涩并见亦示阳气郁遏、血行滞涩；四主噎隔内伤，为内伤噎隔之主脉。四类相互关联：阴血枯竭为根本，精血内竭、噎隔内伤皆由此生；气郁血滞则为阴血不足、脉道不利之兼象。总以阴血亏虚、津液耗损为核心，兼见郁滞与内伤之变。", "c": [{"name": "主阴血枯竭", "desc": "沉主里，涩主血少津枯。原文以左寸沉涩为心血枯、左关沉涩为肝血竭、尺脉沉涩为肾水虚、右关沉涩为脾阴绝、胃脉沉涩为胃汁干，层层推演阴血津液枯竭之机，故沉涩脉主内伤日久、阴血耗损。"}, {"name": "主精血内竭", "desc": "尺脉沉涩，沉主里、涩主精血不足，原文直指为阴精内竭，见于女劳疸肾虚之根。尺部候肾，沉涩则肾精亏耗、阴血不充，故主精血内竭、肾虚之候。"}, {"name": "主气郁血滞", "desc": "原文谓昨朝脉沉涩，沉涩主阴血滞涩、阳气郁遏；今涩减而尺微弦，示郁滞渐开。沉涩并见，非独血少，亦主气血郁滞、阳气不得宣通，故为郁滞之脉。"}], "n": {"主阴血枯竭": 1, "主精血内竭": 1, "主气郁血滞": 1}, "a": {"3040": "主气郁血滞", "24721": "主阴血枯竭", "24905": "主精血内竭"}, "t": 3, "np": 0}, "c:细+缓": {"o": "细缓脉总以虚与湿为纲。细主阴血不足、脉道不充，缓主脾虚湿滞、病势尚缓。三案所示：案1脾虚作泻、经闭虚劳，脉细缓不涩不数，真阴未伤，病机重点在脾虚湿滞、血源不足；案2湿热生虫，阴液已虚，脉细缓，缓非虚寒乃湿热蕴结、正气渐耗；案7遗精止、内热盗汗退，脉细缓，示肾阴尚虚而虚象渐和。三者均以虚为基础，或偏脾虚湿滞，或偏阴血不足，或为虚象渐和之候，缓脉始终提示病势尚缓、胃气未败。", "c": [{"name": "主脾虚湿滞", "desc": "细为血少阴伤，缓主脾虚有湿。原文案1脉细缓，患者素脾虚作泻，因悲恸经闭，腹胀作泻，脉不涩不数，示真阴未伤而脾虚湿滞，血源不足；案2脉细缓，湿热生虫，缓为湿热内蕴，非虚寒之缓，乃湿热蕴结、正气渐耗之象。"}, {"name": "主虚象渐和", "desc": "缓主病势尚缓、胃气渐和。案7遗精已止，内热盗汗均退，肝阳疏泄之势渐平，下元封藏已固，脉来细缓，细为肾阴尚虚，缓示虚象渐和而未尽，惟间或口干、劳动气急，肾阴未复、气不收纳，治宜补肾益气。"}], "n": {"主脾虚湿滞": 2, "主虚象渐和": 1}, "a": {"16208": "主脾虚湿滞", "16438": "主脾虚湿滞", "16522": "主虚象渐和"}, "t": 3, "np": 0}, "pc:六+数+紧": {"o": "六·数紧脉总起来主肝火挟痰、火痰上扰之证。紧脉主痰结、主肝火亢盛，数脉主火盛、主热象急迫，二者相合，提示火痰交炽、有升无降。原文两段均见头晕不寐、少寐头晕，断为肝火挟痰，防其类中或仆中，说明此脉所主以肝火亢盛、痰火互结、上扰清窍为核心。其下属数洪紧脉主热盛邪实、表里俱病，数浮紧脉主湿热痹阻、风邪夹湿，虽具体病位有别，但总不离火热与实邪壅结。各类之间以火盛为本，痰结为标，火痰相合则上扰清窍，甚则动风昏仆，故临证须防类中。", "c": [{"name": "主肝火", "desc": "紧数相合，紧为弦急之甚，主肝火亢盛；数主热象，火性急迫故脉数。原文两段均言'肝火挟痰'，紧数并见说明火性急迫、肝火亢盛，故主肝火为患。"}], "n": {"主肝火": 2}, "a": {"2199": "主肝火", "4808": "主肝火"}, "t": 2, "np": 0}, "pc:两+浮+空": {"o": "浮空脉总属虚证，以气虚为核心，并涉及内伤虚损、阴阳失调。其脉象浮取即得而中空无力，浮为气机浮越于外，空为正气不足于内，故非外感表邪，而是内伤虚损之征。从分部看，右寸虚主肺气不足，右关虚主中气不足，左寸虚主心气不足，左关虚主肝胆气弱，两尺虚主肾气不足，诸部皆虚，故主气虚眩晕、气短乏力等症。若因劳倦努挣伤气，阴乘阳位，则见便后寒热似外感，寸脉浮空，关尺微细，此乃阴阳不相维系、脾肾气弱之象。误用滑利驱导，更致阴虚泉竭，肠澼下注。可见浮空脉所主病机以气虚为纲，内伤虚损、阴阳失调为目，二者相互关联，总不离乎正气亏虚。", "c": [{"name": "主气虚", "desc": "浮空脉以浮为气、空为虚，总属气虚。原文谓“脉浮而空，浮则为气，空则为虚”，且分候右寸肺气不足、右关中气不足、左寸心气不足、左关肝胆气弱、两尺肾气不足，诸部皆虚，故主气虚眩晕、气短乏力等症。"}], "n": {"主气虚": 2}, "a": {"3450": "主气虚", "24801": "主气虚"}, "t": 2, "np": 0}, "pc:两+浮+虚": {"o": "两·浮虚脉总属正虚之象，其浮为风象之假，虚为内伤之真。所主病机以劳倦伤中、阳明不治为核心，进而导致气血不荣、营卫不和。浮虚脉虽见于外，实因内虚，故不可作风寒湿痹论治。三类病机相互关联：劳倦伤中为始因，阳明不治为关键，营卫不和为表现，总以补益阳明气血为法。", "c": [{"name": "主内虚", "desc": "浮虚脉虽见浮象，但按之无力，为内虚之征。原文指出‘内虚者，脉亦浮而无力’，并强调‘劳倦伤中’致‘卫中空虚’，故浮虚脉主正气内虚，尤以劳倦伤中、气血不足为要。"}], "n": {"主内虚": 2}, "a": {"4490": "主内虚", "5011": "主内虚"}, "t": 2, "np": 0}, "pc:六+弦+弱": {"o": "弦弱脉总起来主中气虚弱、肝木乘脾、虚中夹滞及虚寒腹痛。其核心病机为虚与滞并存：弱脉主气虚，反映中气亏虚；弦脉主肝木、主痛，反映肝木乘脾、气机不畅。二者并见，说明因过服发散消导之剂损伤胃气，中气亏虚，木来乘土，故见胃脘当心而痛。弦弱相合，虚中夹滞，治当补而敛之，以芍药甘草汤加桂枝、饴糖等温中缓急、抑木扶土。各类病机相互关联，总以中虚为本，肝乘为标，虚寒腹痛为具体表现。", "c": [{"name": "主中气虚", "desc": "脉弱主气虚，六脉皆弱反映中气亏虚。因过服发散消导之剂损伤胃气，中气不足故脉弱，伴胃脘当心而痛，法当补而敛之。"}], "n": {"主中气虚": 2}, "a": {"6030": "主中气虚", "6324": "主中气虚"}, "t": 2, "np": 0}, "c:洪+紧": {"o": "洪紧脉总起来主火盛邪结、热毒壅盛之证。洪为火盛，紧为邪结，二者相合，反映火热内盛而兼邪气结聚，气血壅滞不通。所主病机主要有三类：一为火盛，火热内盛则脉洪；二为邪结，邪气壅滞则脉紧；三为热毒壅盛，洪紧并见，热毒炽盛，气血壅滞，常见于疔毒肿痛等证。三类之间相互关联：火盛为热毒之源，邪结为壅滞之因，热毒壅盛则是洪紧脉的典型综合病机。原文以疔毒案为例，左脉洪紧，断为肝火炽盛、毒火内攻，正是火盛与邪结相合为患。故洪紧脉总以实热壅结为纲，虚寒证少见。", "c": [{"name": "主火盛", "desc": "洪脉为火盛之象，原文'洪为火盛'直接点明。火热内盛，气血涌盛，故脉形洪大。如臂上生疔毒案，左脉洪紧，断为肝火炽盛，毒火内攻，热痰上壅，成痰厥之证。"}], "n": {"主火盛": 2}, "a": {"19969": "主火盛", "20377": "主火盛"}, "t": 2, "np": 0}, "pc:尺+大+散": {"o": "尺·大散脉总属虚候，以正气耗散、阴阳亏虚为纲。散大脉主中气虚寒、气不固摄；濡软脉主气血不足、脉道失充；尺脉浮大主真火外越、虚阳浮越；尺脉沉数主真阴内竭、虚热内生。四类病机皆从'虚'字着眼：中气虚寒与气血不足偏于中焦气分，真火外越与真阴内竭偏于下焦阴阳。散大、濡软为气散不敛之象，浮大、沉数则为阴阳离决之兆。诸类之间相互关联，气虚无以生血则气血两虚，阳虚不能守位则虚阳外越，阴虚不能制火则虚热内炽，总以本虚为主，治当温补升提、引火归元、滋阴降火，随脉象而施。", "c": [{"name": "主中气虚寒", "desc": "脉见散大，散为气散不收，大而无力，是正气耗散、中焦虚寒之象。原文'脉见散大，中气虚寒'及'脉散大者，中气不足'直接点明，散大脉主中气亏虚、气不固摄，故见遗尿等症。"}], "n": {"主中气虚寒": 2}, "a": {"24641": "主中气虚寒", "24642": "主中气虚寒"}, "t": 2, "np": 0}, "pc:两+细+虚": {"o": "两·细虚脉总起来主正气亏虚，尤以津液元气俱伤为核心。其脉虚细，小弱虚细皆主正虚，数则示虚热。原文因克削过甚，致津液元气俱伤，故见舌燥无津、手指蠕动、心悸不寐、面色黯淡等症。三类病机相互关联：正虚为根本，津伤为阴液耗损之具体表现，虚热为阴虚不制阳之继发结果，三者常并存，反映虚损性病证的不同侧面。", "c": [{"name": "主虚", "desc": "脉虚细主正气亏虚。原文右脉小弱、左脉虚数，两脉虚细，小弱虚细皆主正气亏虚，因克削过甚，津液元气俱伤，故见面色黯淡、舌燥无津、手指蠕动、心悸不寐等虚象。"}], "n": {"主虚": 1}, "a": {"758": "主虚"}, "t": 1, "np": 0}, "c:沉+动": {"o": "沉动脉总起来主气机内敛与邪正相争之病机。其脉沉主里、主气机内收，动则示气血扰动或正气抗邪。从所主看，一类为气逆渐平、胃气复降之顺象，脉沉静而动气下移中脘；一类为里热未清、正气抗邪，见于数沉动脉，数主热、沉主里，生动之机示正邪相争；一类为血伤邪扰，见于沉细动脉，沉细示病位在肾，动止不匀示痧邪扰气血，兼有阴血不足。三类之间，气逆渐平属气机复常之转归，里热未清与血伤邪扰则属邪正交争、气血失和之病态，总以沉静为气敛、动数为邪扰为辨。", "c": [{"name": "主气逆渐平", "desc": "脉沉静而四动近常，示气机内敛不浮；动气下移中脘而静，说明上逆之气渐降，中焦气机趋于安和，故主气逆渐平、胃气复降之机。"}], "n": {"主气逆渐平": 1}, "a": {"2950": "主气逆渐平"}, "t": 1, "np": 0}, "pc:右+微+结": {"o": "右·微结脉总起来主痰阻脉络兼正气略伤。结脉主痰块堵塞隧道，气血运行不畅；微脉示正气略伤。二者并见，反映痰饮内阻、正气渐损之病机。原文以伏暑夹痰饮为例，屡治热不退、痰不除，右脉微结，针后出紫血、咳老痰而愈，证实痰去则脉通。故本脉所主以痰阻为核心，正伤为兼，痰阻与正伤相互影响，痰阻日久伤正，正伤则痰更难化，形成虚实夹杂之候。", "c": [{"name": "主痰阻", "desc": "右脉微结，结脉主痰块堵塞隧道，气血运行不畅。原文载‘中有块痰，堵塞隧道’，针后咳出老痰则用药见效，证实结脉所主为痰阻脉络，痰去则脉通病愈。"}], "n": {"主痰阻": 1}, "a": {"5519": "主痰阻"}, "t": 1, "np": 0}, "pc:尺+滑+弱": {"o": "尺·滑弱脉总以尺部弱、关部滑为特征，主本虚标实之证。其病机核心为肝肾两虚、虚风痰阻：尺弱反映肝肾阴血不足，关滑提示内风痰浊壅盛。虚风因虚而动，痰随风升，阻滞络脉，故见舌强肢麻、口眼㖞斜、溲多筋酸等症。三类病机相互关联：肝肾两虚为病之本，内风痰阻为病之标，虚风煽络为虚与风痰相合之果。总属正虚邪实、本虚标实，治当益肾之阴以涵木，使风定痰消。", "c": [{"name": "主肝肾两虚", "desc": "尺脉弱为肾虚之征，原文谓“肝肾两虚”，症见溲多、筋酸、左手不仁，由血不养筋、营卫俱虚所致，故尺弱主肝肾阴血亏虚。"}], "n": {"主肝肾两虚": 1}, "a": {"11648": "主肝肾两虚"}, "t": 1, "np": 0}, "pc:右+疾+促": {"o": "右·疾促脉在此案中总属阴亏阳亢、本虚标实之候。右脉虚细主阴气大亏，左脉促疾主阳气偏亢，二者并见，揭示‘阴气大亏，阳气偏亢’的核心病机。阴亏为本，阳亢为标，阳亢化火，上灼肺金则咳喘汗多，中乘脾土则便溏不食，下扰膀胱则溺痛频数。诸类病机以阴亏阳亢为枢，火烁肺金与木乘土位为变，总成劳瘵之形。脉象促疾与虚细同现，正是虚火内炽、真阴耗损之征，故其主病虽涉多端，皆不离‘水亏木横、火烁肺金’之总纲。", "c": [{"name": "主阳亢", "desc": "左脉促疾，为阳气偏亢之象。原文谓‘促疾为阳亢’，因阴亏不能制阳，阳热亢盛，鼓动血脉急迫，故脉来促疾。伴舌红燥裂、溺窍灼痛、小溲频数等热象，皆阳亢火盛之征。"}], "n": {"主阳亢": 1}, "a": {"14835": "主阳亢"}, "t": 1, "np": 0}, "pc:关+虚+小": {"o": "关·虚小脉总起来主气血两亏、失血及中焦虚损。其脉象虚小乏力，为气血不足之征；关部见芤，则专主失血。原文指出‘虚小为气血两亏，芤主失血，关候中焦’，因经水淋漓月余不止，去血过多，阴亏阳弱，故脉见虚小兼芤。三者相互关联：失血为直接病因，气血两亏为病机本质，中焦虚损为病变部位。总属虚证，治宜益气扶阳、固气统血，不可纯用阴柔之品。", "c": [{"name": "主气血两亏", "desc": "六脉虚小乏力，虚小为气血不足之象。原文谓‘虚小为气血两亏’，经水淋漓月余不止，去血过多，阴亏阳弱，故脉道充盈不足而见虚小乏力。"}], "n": {"主气血两亏": 1}, "a": {"15847": "主气血两亏"}, "t": 1, "np": 0}, "c:洪+软": {"o": "洪软脉总起来主气分热盛与气阴两伤并见之候，或阴阳并虚、虚风鼓动之证。洪为气浮于外或热盛于气分，软则中候无力，为气阴不足或阴阳并虚。二者相合，非实热之洪，乃虚阳浮越、虚风内动之象。三类病机相互关联：阴阳并虚为根本，虚风鼓动为变证，气阴两伤为常见转归。多见于热邪久羁、耗气伤阴，或失血日久、气随血脱，或攻治太深、真元日削之证。", "c": [{"name": "主阴阳并虚", "desc": "洪为气浮于外，软则中候无力，合之见阴阳并虚。原文谓'脉洪而软，阴阳并虚'，因攻治太深、真元日削，气血不能内守，虚阳浮越，故脉洪大而软。"}], "n": {"主阴阳并虚": 1}, "a": {"17344": "主阴阳并虚"}, "t": 1, "np": 0}, "c:迟+空": {"o": "迟空脉总属阳气虚衰、脉道不充之象。迟主阳微，空主脉道空虚，二者相合，反映中下焦阳气虚弱，温运失职。阳气不足则水湿不化，暑湿等外邪易内困，形成阳虚湿困之证。临床可见体倦、肤黄、足软、舌白等症。其病机以阳虚为本，湿困为标，虚实夹杂。治疗当以扶阳为主，兼以理湿，使阳气复则湿邪自化。", "c": [{"name": "主阳虚", "desc": "脉迟为阳气不振，空为脉道不充，阳虚不能温运，故见体倦、足软、舌白等症。原文'迟为阳微'直接点明阳虚病机，中下阳微是核心。"}], "n": {"主阳虚": 1}, "a": {"18092": "主阳虚"}, "t": 1, "np": 0}, "pc:左+紧+迟": {"o": "左紧迟脉总起来主寒凝气滞、阳气虚衰、瘀血内停之证。其脉象以紧迟为主，紧迟应寒，弦主气滞疼痛；左弦紧突出寒邪引动厥气上逆、肝脉拘急，右沉细无力侧重阳气虚衰。各类病机相互关联：寒邪外受或苦寒伤阳为诱因，寒凝导致气滞，气滞则血瘀，瘀滞下焦，膀胱气化不利；阳虚则寒凝更甚，形成恶性循环。故紧迟脉所主病机以寒为核心，气滞、血瘀、阳虚为寒邪作用下不同阶段的病理表现，临床当结合兼脉及症状辨析。", "c": [{"name": "主寒在脏", "desc": "原文“脉迟在脏”指出迟脉主脏病，脏病多寒；紧脉亦主寒。左紧迟脉并见，提示寒邪在里、阳气受困，故主寒在脏之病机。"}], "n": {"主寒在脏": 1}, "a": {"21801": "主寒在脏"}, "t": 1, "np": 0}, "pc:六+浮+涩": {"o": "浮涩脉由浮与涩相合而成。浮为阳脉，主表、主阳；涩为阴脉，主血少、主阴分不足。原文以浮、沉、长、短、滑、涩分阴阳，明言涩属阴，浮属阳，故浮涩脉总属阴阳相兼之脉，非独主一病。其病机要点有三：一为阴分不足，涩主阴血亏虚、脉道不利；二为阴阳相兼，浮阳与涩阴并见，示阴阳互根、相合为用之常；三为气血不充，浮取见涩，为阴血不足而阳气浮越之象。三者相互关联：阴血亏虚是基础，阴阳相兼是脉象表现形式，气血不充是具体病机。浮涩脉既可见于生理性阴阳相合，亦可见于病理性阴血不足，须结合其他脉症综合判断。", "c": [{"name": "主阴", "desc": "原文以浮、沉、长、短、滑、涩分阴阳，明言“沉、涩、短者，阴也”，浮涩脉中涩属阴，故主阴。其脉象涩滞不利，为阴血不足、脉道不充之征，与浮阳相兼，示阴阳相合之机。"}], "n": {"主阴": 1}, "a": {"21810": "主阴"}, "t": 1, "np": 0}, "pc:六+微+涩": {"o": "微涩脉总起来主气血亏虚、血行滞涩及冲任虚损。脉微为气血不足之象，涩为血行不畅之征，二者相合，多见于虚中夹滞之证。原文'赤白带下，日久黄瘁，六脉微涩'，因带下日久，耗伤气血，冲任虚损，湿浊下注，故脉见微涩。气血亏虚则脉微，血行滞涩则脉涩，冲任虚损则带下不止，三者相互关联，共同构成虚损夹滞的病机。微涩脉所主，以虚为本，以滞为标，虚滞并存，反映了久病耗伤、虚实夹杂的病理特点。", "c": [{"name": "主气血亏虚", "desc": "脉微主气血亏虚，因气血不足，脉道不充，故脉象微弱；原文'六脉微涩'伴'日久黄瘁'，黄瘁为气血亏虚之面色，带下日久耗伤气血，故脉微主气血亏虚。"}], "n": {"主气血亏虚": 1}, "a": {"27045": "主气血亏虚"}, "t": 1, "np": 0}, "pe:六+洪": {"o": "洪脉总以热盛为核心，脉体阔大、来盛去衰，为阳热亢盛、气血燔灼之象。所主病机可分虚实两端：实者热邪充斥，或为实热毒盛，或为气分热盛，或湿热痰郁搏结，脉多洪盛有力；虚者至虚有盛候，虚阳外浮，脉洪而空软无根，甚则但洪无胃气而为危候。各段原文所示，洪脉主热之常，兼滑缓则夹痰湿，兼数则热毒亢盛，兼微则热在肺经气分；若按之搏指而形色衰惫，则舍脉从症，断为虚阳外浮。故洪脉虽总主热，须辨有力无力、有根无根，以分实热、虚火与胃气存亡，不可一概攻伐。", "c": [{"name": "主实热", "desc": "洪脉体阔大，来盛去衰，为阳热亢盛之象。原文见'六脉洪盛有力，沉取亦然'，伴便秘溲赤、渴欲冷饮、痘色紫红，断为实热毒盛；又'脉本洪数'主痹症夹痰饮之热邪偏盛。洪而有力，热邪充斥内外，故主实热证。"}, {"name": "主虚阳外浮", "desc": "洪脉亦见于至虚有盛候。原文'六脉洪盛，按之搏指'，但形色衰惫，断为心肺俱虚、虚阳外浮，法当补中；又'洪大，按之则绝'，为无胃气之危候。洪而空软无根，乃虚阳浮越，不可误作实热攻伐。"}, {"name": "主热毒壅盛", "desc": "洪盛有力，沉取亦然，兼便秘溲赤、口气臭、渴欲冷饮、痘色紫红板滞，脉证相参确系实热毒盛。热毒壅遏气血，脉道充盈，故洪盛搏指。原文用二花解毒汤加大黄清热攻实，待热毒衰其大半即止，示洪脉主热毒壅盛之实证。"}, {"name": "主胃气衰败", "desc": "洪脉以胃气为本，若但洪无胃气则危。原文小儿'脉洪大，按之则绝'，六脉单洪，值夏月，断为'但洪无胃气'，引《经》'洪多胃气少曰病，但洪无胃气曰死'。洪而无根、按之即绝，乃胃气已败之死候，故主胃气衰败。"}], "n": {"主实热": 1, "主虚阳外浮": 1, "主热毒壅盛": 2, "主胃气衰败": 1}, "a": {"5451": "主实热", "12185": "主热毒壅盛", "12186": "主热毒壅盛", "17340": "主虚阳外浮", "17459": "__np", "21797": "__np", "27865": "主胃气衰败"}, "t": 7, "np": 2}, "pe:尺+短": {"o": "尺·短脉总属虚损之候，以气虚、阳虚、气血两虚为基本病机。短主气损，脉气不充，故短而无力多主气虚，尤以肺气、心气不足为常见；寸脉短少力弱于关尺，则为阴盛阳虚、阳不上充，主阳虚寒盛；尺脉短小、心脉短、肝脉虚，示心气亏虚、肝血不足、肾气亦弱，属虚损；六部豁大浮中沉无力而短，主气血两虚、中阳不足。若短而兼屋漏、雀啄等怪脉，则非寻常虚损，乃胃气败绝之死候。各类之间，以虚为本，或偏气虚，或偏阳虚，或气血两虚，甚则脏气败绝，总不离乎正气亏少、脉道不充。", "c": [{"name": "主气虚", "desc": "短脉主气病，气虚不能充达。如原文“寸口之脉中手短者，曰头痛”，短则气病，气虚不能上充；又“寸脉短少及力少于关尺者，此阴盛阳虚也”，短少力弱为阳气不足。故短脉主气虚，尤以肺气、心气不足为常见。"}, {"name": "主阳虚寒盛", "desc": "寸脉短少而力弱于关尺，为阴盛阳虚、阳不上充，症见胸膈满闷、腹中胀满、身体拘急、手足厥冷，急宜温中。短而无力伴寒象，主阳虚寒凝，阳气不能布达。"}, {"name": "主气血两虚", "desc": "六部俱豁大、浮中沉无力而短，虽痛虽发热而脉无力，慎柔断为虚寒，主气血两虚、中阳不足。短而无力，为气血亏少、元气不充，故见下红血桶、痛不可忍、发热流汗等症，益气正宜。"}, {"name": "主胃气败绝", "desc": "脉来如屋漏、雀啄等怪脉，短而绝止不相联续，无胃气柔和之象，为脏气败绝之死候。短脉若兼怪脉形态，非寻常虚损，乃胃气将绝、生机已息之危象。"}], "n": {"主气虚": 2, "主阳虚寒盛": 1, "主气血两虚": 1, "主胃气败绝": 1}, "a": {"3511": "主气血两虚", "12439": "主气虚", "21823": "主胃气败绝", "22760": "主气虚", "24237": "主阳虚寒盛"}, "t": 5, "np": 0}, "pe:双+平": {"o": "双·平脉在《金匮》饮病诸段中，总以水饮为病机核心，兼涉寒、虚。脉双弦主寒，偏弦主饮，脉沉滑主留饮，脉微、脉虚主阳虚，脉平则饮邪未甚。诸脉随饮停部位浅深及体质虚实而异，说明水饮为病脉无定象，当结合喘满、短气、咳唾引痛、身体疼重等症合参。其关系为：饮邪凝聚致脉弦，寒邪收引亦致弦，阳虚不化则脉微虚，水饮内结则脉沉滑，四类病机相互兼夹，总不离饮停气阻、阳虚寒凝之旨。", "c": [{"name": "主饮", "desc": "脉弦为饮邪凝聚、气机拘急之象。原文以偏弦主饮，双弦亦为饮邪偏盛；留饮脉沉滑，沉主水饮内停，滑为水饮内结。四饮证候如痰饮水走肠间、悬饮咳唾引痛、溢饮身体疼重，皆饮停气阻所致，故脉见弦、沉、滑等，总属饮病之脉。"}, {"name": "主寒", "desc": "原文明确提出“脉双弦者寒也”，弦脉主寒，因寒性收引、脉道拘急，故见弦象。双弦为寒邪偏盛，且多出现在大下后，提示下后里虚，寒从内生，阳虚不能温煦，寒凝气机，脉道紧张而呈双弦。"}], "n": {"主饮": 2, "主寒": 1}, "a": {"21659": "主寒", "22018": "主饮", "23563": "主饮"}, "t": 3, "np": 0}, "ps:两寸+大": {"o": "两寸大脉总主上焦病机，以邪实热盛为多，虚证较少。其大而有力者，多主热盛、气火上逆、痰火壅盛或邪实于上，因寸候上焦，大则阳热有余、邪气壅盛，故见头眩呕吐、咳喘鼻渊、眼赤肿痛等。若大而兼滑，则痰火交阻；浮大则气火上升；洪大则热壅营分。若两寸大而两尺沉微，则属上盛下虚，热壅于上而阳衰于下。至于大而弱无力，则又为气血不足之虚证，不可一概作实热论。诸类之中，热盛、气火、痰火、邪实四类多相兼夹，总以“上焦邪实热壅”为纲；上盛下虚为复合病机；虚证则属变例。临证须参合尺脉及症候，辨其虚实寒热。", "c": [{"name": "主热盛", "desc": "两寸脉大（洪大、滑大）主上焦热盛。寸候上焦，大则阳热有余，故见心烦、汗出、颧红唇红、舌绛且干等。如营热气泄、温病邪热入营、血痢呕吐，皆以寸大示热壅于上。"}, {"name": "主气火上逆", "desc": "两寸浮大或洪大，主肝阳化火、气火上冲。寸主上焦，浮大为阳亢之象，故见头眩、呕吐、脘闷头胀、耳鼻窍闭。如厥阴上干、少阳郁热上逆犯肺、郁怒化火，皆气火上升之候。"}, {"name": "主痰火壅盛", "desc": "两寸关脉滑大有力，主痰火壅盛于中上二焦。滑主痰，大主邪实，痰火随气上逆，故见眼赤肿痛、白泡突生、呕吐眩晕、心痛彻背。如等段，皆断为“中焦有痰，肝胆有火”或痰积胸膈。"}, {"name": "主邪实于上", "desc": "两寸脉大而见咳嗽、鼻渊、喷嚏等，主清邪或风寒郁热壅于上焦。寸候肺卫，大示邪气盛于上，非虚也。如暑风清邪中上、风寒化热壅肺致鼻渊，脉大与邪实于上相应。"}, {"name": "主上盛下虚", "desc": "两寸脉洪大或滑大，两尺沉微或沉弱，主上焦热盛（或痰火）而下元虚寒（或血虚）。寸大示热壅于上，尺沉微示阳衰于下，故见上热下寒、胃痛吐逆、眼赤肿等。如等段，皆上盛下虚之候。"}, {"name": "主虚证", "desc": "两寸关脉大而弱，或大而无力，主气血不足、大虚之证。大则为虚，弱为气血衰少，寸关候上中焦，虚象显著。如反胃日久，脉大而弱，断为气血不足、脾胃虚衰，与实热之大脉不同。"}], "n": {"主热盛": 9, "主气火上逆": 3, "主痰火壅盛": 7, "主邪实于上": 1, "主上盛下虚": 6, "主虚证": 1}, "a": {"807": "主气火上逆", "880": "主邪实于上", "898": "主热盛", "1016": "主热盛", "2183": "主热盛", "3829": "主上盛下虚", "3899": "主痰火壅盛", "4287": "主上盛下虚", "4302": "主痰火壅盛", "6103": "主热盛", "6109": "主上盛下虚", "6117": "主热盛", "6138": "主痰火壅盛", "6170": "主上盛下虚", "6192": "主热盛", "6218": "主上盛下虚", "6397": "主热盛", "6403": "主上盛下虚", "6412": "主热盛", "6433": "主痰火壅盛", "6465": "主痰火壅盛", "6487": "主痰火壅盛", "6513": "主痰火壅盛", "15420": "主气火上逆", "18340": "主虚证", "18606": "主气火上逆", "24370": "主热盛"}, "t": 27, "np": 0}, "ps:左寸+弱": {"o": "左寸弱脉总属心之气血不足，然其主病常非单一，多与它部脉象合参而呈本虚标实之候。弱脉本身提示正气亏虚，尤以心血不足为核心；若兼关弦大、右寸关滑大，则主痰瘀互结或痰火壅盛；兼两尺洪大数，则主湿热下注；兼左关虚弦，则主营虚风动。诸类之间，虚为本，痰、瘀、湿、热、风为标，弱脉所主之病机总以正虚为本，邪实为标，虚实夹杂。", "c": [{"name": "主心血不足", "desc": "左寸弱脉直接反映心气或心血亏虚。原文如‘左寸短弱示心血不足’，‘沉弱主气血不足’，‘左寸细弱’主营虚，均以左寸弱为心之气血不足之征，故主心血不足。"}, {"name": "主痰瘀互结", "desc": "弱脉常与关弦大、右寸关滑大并见，提示痰瘀互结。如‘弦大滑大主中焦痰盛、肝经瘀血’，‘痰瘀互结、本虚标实’，‘中焦有痰，肝经有瘀血’，左寸弱为兼见之虚象。"}, {"name": "主痰火壅盛", "desc": "左寸短弱而右寸关滑数，主上中二焦痰火。如‘右寸关滑主上中二焦痰火’，‘右寸关滑为脾肺痰火’，弱脉示正气不足，痰火为患。"}, {"name": "主营虚风动", "desc": "左寸细弱兼左关虚弦，主产后营血亏虚、肝风上冒。如‘产后营血亏虚，肝失濡养，肝风上冒’，细弱主营虚，虚弦为肝风内动，故主营虚风动。"}], "n": {"主心血不足": 4, "主痰瘀互结": 1, "主痰火壅盛": 2, "主营虚风动": 1}, "a": {"3791": "主心血不足", "3792": "主痰瘀互结", "4275": "主心血不足", "6240": "主心血不足", "6245": "主痰火壅盛", "6533": "主心血不足", "6538": "主痰火壅盛", "11928": "主营虚风动"}, "t": 8, "np": 0}, "ps:左寸+滑": {"o": "左寸滑脉总起来主痰、火、郁、妊娠及虚损。滑为痰象，洪滑或滑数多主痰火内蕴、心肝火盛；左寸关洪滑又主肝胆郁火、胃中胶痰，属有余之疾。左寸动滑摇摆则为妊娠胎动之征。此外，滑脉亦可见于血虚气弱、阴亏阳浮之虚证，如经带胎产诸病及肝肾阴亏、火动风生之候。各类之间，痰火、火盛、郁火多属实证，妊娠为生理之常，血虚气弱为虚证，体现了滑脉主病有虚实寒热之异，须结合兼脉及症情合参。", "c": [{"name": "主痰火", "desc": "滑脉主痰，洪滑或滑数多属痰火内蕴。原文如左寸洪滑，断为心肝火盛、痰热内扰；左寸关洪滑，谓胃中胶痰、肝胆郁火；左寸关滑数，言火动风生、风动痰生。滑为痰聚，洪数为火，故主痰火为患。"}, {"name": "主火盛", "desc": "洪滑之脉，洪主火盛，滑主痰，火象显著。如左寸洪滑，断为肝心二经火盛；洪滑，谓肝胆有郁火；洪滑为火盛痰聚。火性炎上，左寸候心，故左寸洪滑多主心肝火旺。"}, {"name": "主郁火", "desc": "滑脉兼洪，见于左寸关，主肝胆郁火。原文左寸关洪滑，断为肝胆有郁火、胃中胶痰，乃有余之疾；同。木郁则达之，火郁则发之，滑脉反映郁火与痰搏结，故主郁火。"}, {"name": "主妊娠", "desc": "左寸脉动滑，有摇摆之状，为妊娠之脉。原文及均言怀孕月余，左寸脉动滑，摇摆不定，乃胎气初结、血聚养胎之象。动滑摇摆为胎动之征，故主妊娠。"}], "n": {"主痰火": 1, "主火盛": 2, "主郁火": 2, "主妊娠": 2}, "a": {"6003": "主火盛", "6166": "主郁火", "6297": "主火盛", "6461": "主郁火", "15024": "主痰火", "16528": "主妊娠", "16532": "主妊娠"}, "t": 7, "np": 0}, "ps:左尺+大": {"o": "左尺大脉总属肾之病机，以虚为本、以实为标。其大非实热壅盛之洪大，乃肾气不固、虚阳下浮之象；或肾阳亏虚，水饮不化而泛溢；或肝火下汲，龙雷升动而灼阴。三者皆根于肾虚失藏，或兼饮邪，或兼火邪，然总以封藏失职、阳气不潜为核心。故左尺脉大，主肾虚不固、肾亏饮泛、火及肾阴三类，治当固肾摄纳、温肾化饮、滋肾泻火，总以敛浮越、复封藏为要。", "c": [{"name": "主肾虚不固", "desc": "左尺候肾，脉独大提示肾气封藏失职、虚阳下浮。原文见左尺脉独大，于通补方中加封固肾气法，以敛浮越之气，说明大脉主肾气不固、下焦摄纳无权。"}, {"name": "主肾亏饮泛", "desc": "肾阳亏虚，水饮不化，上泛为痰饮。原文载“肾亏故左尺脉弦而大”，咳久伤阴、积饮生痰，脉弦大为肾虚饮泛、阳气不藏之象，故大脉主肾亏而寒饮内停。"}, {"name": "主火及肾阴", "desc": "肝火拂逆，下汲肾阴，龙雷之火升动。原文治肝火不得卧，见“左尺脉大”则用家秘肝肾丸，说明大脉主火邪亢盛、灼伤肾阴，治从肝肾以泻火滋阴。"}], "n": {"主肾虚不固": 1, "主肾亏饮泛": 2, "主火及肾阴": 1}, "a": {"5284": "主肾虚不固", "13698": "主肾亏饮泛", "14823": "主肾亏饮泛", "24925": "主火及肾阴"}, "t": 4, "np": 0}, "pc2:右关+滑+沉": {"o": "右关沉滑脉总属脾胃实邪内结之象。沉主里，滑主痰、食、气滞，右关候脾胃，故其病机核心为脾胃运化失司，实邪（痰浊、食积、气食相凝）内停，导致胃气不和。五类病机中，痰浊内蕴、食积内停、气食相凝、胃气不和、内伤饮食，皆围绕中焦脾胃，或为痰食互结，或为气食相凝，或为饮食自伤，或致胃气上逆。各证可单独出现，亦可相兼为病，如痰食交阻、气食相凝。其共同特点为邪实内壅，脉象沉滑有力，治当以祛邪消导、化痰行气、和胃降逆为主。", "c": [{"name": "主痰浊内蕴", "desc": "右关沉滑，沉主里，滑主痰，右关候脾胃，故痰浊内蕴脾胃。原文言‘浊痰之弥漫，心窍之闭阻’，虽心窍稍开，但右关沉滑有力，示痰火内结，风火未平，见手足不遂、口眼㖞斜等症。"}, {"name": "主食积内停", "desc": "右关沉滑，滑主宿食，沉主里滞，右关候脾胃，故为食积内停之征。原文明言‘右关沉滑，乃是食积’，亦以右关沉滑为胃中不和、饮食停积，致食入即吐。"}, {"name": "主气食相凝", "desc": "右关沉滑，气机郁滞与食积相搏，结于中焦。原文曰‘右关沉滑，气食相凝’，指出气食相凝可致口噤不语，属实证。"}, {"name": "主胃气不和", "desc": "右关沉滑，沉主里，滑主痰饮宿食，反映胃中不和、通降失职。原文以右关沉滑为‘胃不和’之据，结合左关小弦，断为肝不疏、胃气不降，故呕吐。"}, {"name": "主内伤饮食", "desc": "右关（气口）脉沉滑，为内伤饮食之征。原文论内伤饮食及劳役不节，皆不足之病，必见于右手，气口脉大，右关沉滑即其具体表现，示饮食不节伤及脾胃。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主痰浊内蕴": 1, "主食积内停": 1, "主气食相凝": 1, "主胃气不和": 1, "主内伤饮食": 1, "其他": 0}, "a": {"7236": "主痰浊内蕴", "15872": "主胃气不和", "19322": "主内伤饮食", "24629": "主气食相凝", "25037": "主食积内停"}, "t": 5, "np": 0}, "pc2:左尺+软+迟": {"o": "左尺软迟脉总属肾虚，以尺脉分候肾中阴阳水火。其核心病机为肾之真阴真阳不足：左尺虚弱细数主肾阴亏虚、虚火内生；右尺迟软主命门相火不足、阳虚不能鼓动；两尺微弱则阴阳俱虚。三者可单独出现，也可并见，反映肾中阴阳互损。进一步可致三阴亏损、虚热无火之劳瘵，出现虚热起伏、衄吐血等虚火妄动之象。诸类之间以肾虚为本，阴虚、阳虚、阴阳两虚为不同层次，虚火劳瘵为阴虚火旺之发展。治疗上分别用六味丸、八味丸、十补丸及补中益气汤调补，忌苦寒伤脾。", "c": [{"name": "主肾阴虚", "desc": "左尺脉虚弱或细数，为左肾真阴不足之象。阴虚不能制火，故脉细数；虚火内生，可见虚热。原文多次以左尺虚弱细数归为真阴亏虚，治用六味丸，主肾阴不足、虚火妄动之证。"}, {"name": "主肾阳虚", "desc": "右尺脉迟软或沉细数欲绝，为命门相火不足。阳虚不能鼓动，故脉迟软；火衰不能温煦，故见虚寒。原文以右尺迟软主相火不足，治用八味丸，属肾阳命火虚衰之候。"}, {"name": "主阴阳两虚", "desc": "两尺微弱则阴阳俱虚。左尺候肾阴，右尺候命火，两尺皆弱说明肾中阴阳水火俱损。原文指出两尺微弱用十补丸，并归为三阴亏损、阴阳两虚之证，治宜阴阳双补。"}, {"name": "主虚火劳瘵", "desc": "劳瘵之证属足三阴亏损、虚热无火，脉见左尺虚弱细数、右尺迟软，示肾阴亏而虚火妄动。阴虚阳浮，火土太旺金水衰涸，血随火泛而衄吐血。脉象反映元气不摄、虚火上炎，误用知柏则伤脾致泻。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主肾阴虚": 2, "主肾阳虚": 0, "主阴阳两虚": 1, "主虚火劳瘵": 1, "其他": 0}, "a": {"18312": "主肾阴虚", "18336": "主阴阳两虚", "23196": "主虚火劳瘵", "23746": "主肾阴虚"}, "t": 4, "np": 0}, "rc:浮取+弦+浮": {"o": "浮取弦脉总属气机郁滞、筋脉拘急之象，其病机涉及肝郁络瘀、痛证、痰饮、风邪在表、湿热内盛及血虚失血等多类。弦为肝之主脉，主气郁、主痛、主痰饮；浮取则示病位偏表或络脉，常与风邪、湿热相合。各段原文显示，浮弦可单独出现，如血虚风入；亦可兼见沉洪、芤等，如肝郁络瘀兼血虚失血，湿热瘀血互结。诸类之间以气机郁滞为核心，或兼外邪，或兼内热，或兼血虚，总不离肝郁络阻、筋脉失和之机。", "c": [{"name": "主肝郁络瘀", "desc": "浮取弦为肝郁气滞、络脉瘀阻之象。原文言‘弦为肝郁络瘀’，并见胁痛、痰中带血，乃肝经络瘀、血不循经所致。弦脉主气机郁滞，浮取则病位偏表或络脉，故主肝郁络瘀。"}, {"name": "主痛", "desc": "弦脉主痛，因气血郁滞、经脉拘急不通而痛。原文明言‘弦主痛’，症见腰腿大痛、少腹亦痛；痛痹偏左，脉浮弦，亦为筋脉拘急而痛。浮弦示痛因外邪或气滞，经络不通。"}, {"name": "主痰饮", "desc": "弦脉可主痰饮，因饮邪停聚、气机被阻，脉气紧张而弦。原文言‘弦主痰饮’，并见经行紫黑、湿热与瘀血互结；痰挟瘀滞，咳血，亦属痰饮为患。浮弦示痰饮偏表或阻络。"}, {"name": "主风邪在表", "desc": "浮取弦，浮主表、主风，弦主筋脉拘急。原文‘脉息浮弦’，谓血虚之体，风邪乘虚而入，客于经络，致痛痹偏左、痿而不举。浮弦并见，示风邪在表，痹阻不通。"}, {"name": "主湿热内盛", "desc": "浮取弦而沉取洪，洪主热盛，弦主郁滞。原文右脉浮取弦、沉取洪，症见寒热、经行紫黑、腰腿痛，为湿热内盛、与瘀血互结。浮弦示湿热郁于气分或偏表，沉洪则热盛于里。"}, {"name": "主血虚失血", "desc": "浮取弦而重按芤，芤主血虚失血。原文左脉浮取弦，沉取洪大而数，重按即芤，症见痰中带血，为血虚失血、肝络瘀热。弦为肝郁，芤为血虚，浮弦示血虚而气郁于外。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主肝郁络瘀": 1, "主痛": 1, "主痰饮": 0, "主风邪在表": 1, "主湿热内盛": 0, "主血虚失血": 0, "其他": 0}, "a": {"5279": "主肝郁络瘀", "5437": "主痛", "8981": "主风邪在表"}, "t": 3, "np": 0}});